import { devLogger } from '@/app/lib/logging/devLogger';

/**
 * Asset 로딩 실패 시 Fallback 이미지 제공
 */

export class AssetLoadError extends Error {
  constructor(
    public assetId: string,
    public fallbackUrl: string
  ) {
    super(`Failed to load asset ${assetId}`);
    this.name = 'AssetLoadError';
  }
}

/**
 * Asset을 로드하고 실패 시 Fallback 사용
 */
export async function loadAssetWithFallback(
  url: string,
  fallbackUrl: string = '/images/default-action-off.png'
): Promise<string> {
  try {
    const response = await fetch(url, { method: 'HEAD' });
    if (!response.ok) throw new Error('Load failed');
    return url;
  } catch (error) {
    devLogger.warn(`Asset 로딩 실패, Fallback 사용: ${url} → ${fallbackUrl}`);
    return fallbackUrl;
  }
}

/**
 * 여러 Asset을 일괄 로드 (Fallback 포함)
 */
export async function loadAssetsWithFallback(
  assets: Array<{ url: string; fallback?: string }>
): Promise<Array<{ url: string; loaded: string }>> {
  const results = await Promise.all(
    assets.map(async ({ url, fallback }) => {
      const loaded = await loadAssetWithFallback(url, fallback);
      return { url, loaded };
    })
  );
  return results;
}

import { devLogger } from '@/app/lib/logging/devLogger';

/**
 * BGM 플레이어 클래스
 * HTMLAudioElement를 래핑하여 BGM 재생을 관리
 * - 사용자 제스처에서만 재생 시작 (autoplay 정책 준수)
 * - fadeIn/fadeOut 지원
 * - loop, preload 설정
 */

/** BGM 재생 상태 */
export type BgmStatus =
  | 'idle'      // 초기화 전
  | 'loading'   // play() 호출 중
  | 'ready'     // init 완료, 미재생
  | 'playing'   // 재생 중
  | 'blocked'   // autoplay 정책으로 차단됨 (NotAllowedError)
  | 'error'     // 기타 오디오 오류
  | 'disabled'; // disableBgm=true 등 외부에서 비활성화

export class BgmPlayer {
  private audio: HTMLAudioElement | null = null;
  private fadeInterval: number | null = null;
  private isInitialized = false;
  private targetVolume: number = 0.65;
  private eventHandlers: { event: string; handler: EventListener }[] = [];
  private _status: BgmStatus = 'idle';

  get status(): BgmStatus { return this._status; }

  /**
   * BGM 초기화 (재생하지 않음)
   * 사용자 제스처에서 play()를 호출해야 재생됨
   */
  init(srcUrl: string, volume = 0.65): void {
    // 기존 재생 중이면 반드시 stop() 후 교체
    if (this.audio && this.isInitialized) {
      this.stop();
    }
    // 기존 audio 정리
    this.cleanup();

    // 새 audio element 생성
    this.audio = new Audio();
    
    this.audio.src = srcUrl;
    this.audio.preload = 'auto';
    this.audio.loop = true;
    this.audio.volume = volume;
    this.targetVolume = volume;
    this.isInitialized = true;
    this._status = 'ready';
    try {
      // 일부 브라우저에서 src 변경 후 명시적 load가 안정적
      this.audio.load();
    } catch {
      // ignore
    }
    
    // 에러 핸들링 (크래시 방지)
    const errorHandler = (e: Event) => {
      const error = this.audio?.error;
      devLogger.warn('[BgmPlayer] Audio error:', e, error);
    };
    this.audio.addEventListener('error', errorHandler);
    this.eventHandlers.push({ event: 'error', handler: errorHandler });
  }

  /**
   * BGM 재생 시작
   * 사용자 제스처(클릭)에서만 호출되어야 함
   * autoplay blocked 시 조용히 실패 (throw하지 않음)
   */
  async play(): Promise<void> {
    if (!this.audio || !this.isInitialized) {
      devLogger.warn('[BgmPlayer] Not initialized');
      return;
    }

    this._status = 'loading';
    try {
      await this.audio.play();
      this._status = 'playing';
    } catch (error: unknown) {
      const isBlocked =
        error instanceof DOMException &&
        (error.name === 'NotAllowedError' || error.name === 'AbortError');
      this._status = isBlocked ? 'blocked' : 'error';
      devLogger.warn('[BgmPlayer] Play failed:', isBlocked ? 'blocked (autoplay policy)' : 'error', error);
    }
  }

  /**
   * BGM 일시정지
   */
  pause(): void {
    if (this.audio) {
      this.audio.pause();
      // pause 시에도 loop를 false로 설정하여 재생이 계속되지 않도록
      this.audio.loop = false;
    }
  }

  /**
   * BGM 정지 및 리셋
   */
  stop(): void {
    if (this.fadeInterval) {
      clearInterval(this.fadeInterval);
      this.fadeInterval = null;
    }
    if (this.audio) {
      // 모든 이벤트 리스너 제거
      this.eventHandlers.forEach(({ event, handler }) => {
        this.audio?.removeEventListener(event, handler);
      });
      this.eventHandlers = [];
      
      // 기존 오디오 정지 및 완전히 제거
      try {
        this.audio.pause();
        this.audio.loop = false;
        this.audio.currentTime = 0;
        // suspend()를 호출하여 리소스 해제
        if ('suspend' in this.audio && typeof this.audio.suspend === 'function') {
          this.audio.suspend();
        }
      } catch (e) {
        // 무시
      }
      
      // src를 제거하여 재생 중단
      try {
        this.audio.removeAttribute('src');
        this.audio.src = '';
      } catch (e) {
        // 무시
      }
      
      // 오디오 요소를 완전히 제거
      this.audio = null;
      this.isInitialized = false;
    }
    this._status = 'idle';
  }

  /**
   * 볼륨 설정 (0.0 ~ 1.0)
   */
  setVolume(v: number): void {
    this.targetVolume = Math.max(0, Math.min(1, v));
    if (this.audio) {
      this.audio.volume = this.targetVolume;
    }
  }

  /**
   * 음소거 토글
   * volume을 변경하지 않고 audio.muted 속성 사용
   */
  setMuted(muted: boolean): void {
    if (this.audio) {
      this.audio.muted = muted;
    }
  }

  /**
   * 페이드 아웃 (점진적으로 볼륨 감소 후 정지)
   */
  fadeOut(ms = 300): void {
    if (!this.audio || !this.isInitialized) return;

    // loop를 false로 설정하여 fadeOut 후 재생이 계속되지 않도록
    this.audio.loop = false;

    // 기존 fade interval 정리
    if (this.fadeInterval) {
      clearInterval(this.fadeInterval);
      this.fadeInterval = null;
    }

    const startVolume = this.audio.volume;
    const steps = Math.max(10, Math.floor(ms / 16)); // 16ms 간격 (약 60fps)
    const stepSize = startVolume / steps;
    let currentStep = 0;

    this.fadeInterval = window.setInterval(() => {
      currentStep++;
      const newVolume = Math.max(0, startVolume - stepSize * currentStep);
      
      if (this.audio) {
        this.audio.volume = newVolume;
      }

      if (currentStep >= steps || newVolume <= 0) {
        if (this.fadeInterval) {
          clearInterval(this.fadeInterval);
          this.fadeInterval = null;
        }
        this.pause();
        // fadeOut 완료 후 오디오 요소 완전히 제거
        if (this.audio) {
          // 모든 이벤트 리스너 제거
          this.eventHandlers.forEach(({ event, handler }) => {
            this.audio?.removeEventListener(event, handler);
          });
          this.eventHandlers = [];
          
          try {
            // suspend()를 호출하여 리소스 해제
            if ('suspend' in this.audio && typeof this.audio.suspend === 'function') {
              this.audio.suspend();
            }
            this.audio.removeAttribute('src');
            this.audio.src = '';
          } catch (e) {
            // 무시
          }
          
          this.audio = null;
          this.isInitialized = false;
        }
        // 볼륨은 원래대로 복구하지 않음 (stop에서 리셋됨)
      }
    }, 16);
  }

  /**
   * 페이드 인 (점진적으로 볼륨 증가)
   */
  fadeIn(ms = 150): void {
    if (!this.audio || !this.isInitialized) return;

    // 기존 fade interval 정리
    if (this.fadeInterval) {
      clearInterval(this.fadeInterval);
      this.fadeInterval = null;
    }

    const targetVolume = this.targetVolume;
    const steps = Math.max(10, Math.floor(ms / 16)); // 16ms 간격
    const stepSize = targetVolume / steps;
    let currentStep = 0;

    // 시작 볼륨을 0으로 설정
    if (this.audio) {
      this.audio.volume = 0;
    }

    this.fadeInterval = window.setInterval(() => {
      currentStep++;
      const newVolume = Math.min(targetVolume, stepSize * currentStep);
      
      if (this.audio) {
        this.audio.volume = newVolume;
      }

      if (currentStep >= steps || newVolume >= targetVolume) {
        if (this.fadeInterval) {
          clearInterval(this.fadeInterval);
          this.fadeInterval = null;
        }
        if (this.audio) {
          this.audio.volume = targetVolume;
        }
      }
    }, 16);
  }

  /**
   * 리소스 정리 (interval, audio)
   */
  cleanup(): void {
    if (this.fadeInterval) {
      clearInterval(this.fadeInterval);
      this.fadeInterval = null;
    }
    if (this.audio) {
      // 모든 이벤트 리스너 제거
      this.eventHandlers.forEach(({ event, handler }) => {
        this.audio?.removeEventListener(event, handler);
      });
      this.eventHandlers = [];
      
      try {
        this.audio.pause();
        this.audio.loop = false;
        this.audio.currentTime = 0;
        // suspend()를 호출하여 리소스 해제
        if ('suspend' in this.audio && typeof this.audio.suspend === 'function') {
          this.audio.suspend();
        }
        // src를 제거하여 재생 중단
        this.audio.removeAttribute('src');
        this.audio.src = '';
      } catch (e) {
        // 무시
      }
      
      this.audio = null;
    }
    this.isInitialized = false;
  }
}

/**
 * 드래그 앤 드롭 유틸리티
 * 템플릿 ID와 슬롯 week_key 매핑
