'use client';

import Link from 'next/link';
import { useMemo, useState } from 'react';
import { Check, CheckSquare, ChevronDown, FileText, Image as ImageIcon } from 'lucide-react';
import type { PublicNoteBlock, PublicNoteDocument } from '@/app/lib/server/publicNote';
import { buildChildrenByParentBlock, sortRootBlocks } from '@/app/lib/note/noteBlockTree';
import { resolveToggleBodyForDisplay } from '@/app/lib/note/toggleBody';
import { resolveVideoEmbedContent, videoProviderLabel } from '@/app/lib/note/videoEmbed';
import { bulletMarkerForLevel, stripListItemMarkerPrefix } from '@/app/admin/note/_components/noteBulletInput';
import { normalizeTableContent } from '@/app/admin/note/_lib/noteTableBlock';
import { codeLanguageLabel, readCodeLanguage } from '@/app/admin/note/_lib/noteCodeBlock';
import {
  imageBlockAlignClass,
  imageCaptionAlignClass,
  imageFrameWidthStyle,
  readImageAlign,
  readImageWidthPercent,
} from '@/app/admin/note/_lib/noteImageBlock';
import { VideoEmbedFrame } from '@/app/admin/note/_components/VideoEmbedFrame';

function listItemContent(content: Record<string, unknown> | null | undefined) {
  if (!content) return content;
  const rawText = typeof content.text === 'string' ? content.text : '';
  if (!rawText) return content;
  const text = stripListItemMarkerPrefix(rawText);
  if (text === rawText) return content;
  return { ...content, text };
}

function blockDepth(content: Record<string, unknown> | null | undefined) {
  return Math.max(0, Math.min(6, Number(content?.depth ?? 0)));
}

function richHtml(content: Record<string, unknown> | null | undefined, field: 'text' | 'body' = 'text') {
  if (field === 'body') {
    const { text, html } = resolveToggleBodyForDisplay(content);
    if (html.trim()) return html;
    if (!text.trim()) return '';
    return text.split('\n').map((line) => `<p>${line || '<br>'}</p>`).join('');
  }
  const htmlKey = 'html';
  const html = content?.[htmlKey];
  if (typeof html === 'string' && html.trim()) return html;
  const plain = content?.[field];
  if (typeof plain !== 'string' || !plain.trim()) return '';
  return plain.split('\n').map((line) => `<p>${line || '<br>'}</p>`).join('');
}

function RichText({
  content,
  field = 'text',
  className,
}: {
  content: Record<string, unknown> | null | undefined;
  field?: 'text' | 'body';
  className?: string;
}) {
  const html = useMemo(() => richHtml(content, field), [content, field]);
  if (!html) return null;
  return (
    <div
      className={`public-note-rich ${className ?? ''}`}
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}

function PublicBlock({
  block,
  publicPages,
  childBlocks = [],
  lookupChildBlocks,
  renderChildBlock,
  isInsideToggle = false,
}: {
  block: PublicNoteBlock;
  publicPages: Record<string, string>;
  childBlocks?: PublicNoteBlock[];
  lookupChildBlocks?: (parentId: string) => PublicNoteBlock[];
  renderChildBlock?: (child: PublicNoteBlock) => React.ReactNode;
  isInsideToggle?: boolean;
}) {
  const depth = isInsideToggle ? 0 : blockDepth(block.content);
  const indentStyle = isInsideToggle ? undefined : { marginLeft: `${depth * 20}px` };
  const isBorderlessInlineBlock = block.type === 'text' || block.type === 'todo';
  const rootBlockShell =
    isInsideToggle || isBorderlessInlineBlock
      ? ''
      : 'rounded-lg border border-slate-200 bg-white px-3 py-2';

  if (block.type === 'divider') {
    return (
      <div className="py-3" style={indentStyle}>
        <div className="border-t border-slate-200" />
      </div>
    );
  }

  if (block.type === 'table') {
    const table = normalizeTableContent(block.content);
    return (
      <div className={`overflow-x-auto py-2 ${rootBlockShell}`} style={indentStyle}>
        <table className="w-full border-collapse text-left text-[14px]">
          <tbody>
            {table.rows.map((row, rowIndex) => {
              const isHeader = table.hasHeaderRow !== false && rowIndex === 0;
              return (
                <tr key={`row-${rowIndex}`}>
                  {row.map((cell, colIndex) => (
                    <td
                      key={`cell-${rowIndex}-${colIndex}`}
                      className={`min-w-[120px] border border-slate-200 px-2 py-1.5 align-top ${
                        isHeader ? 'bg-slate-50 font-medium text-slate-700' : 'text-slate-800'
                      }`}
                    >
                      <RichText content={cell} className="leading-6" />
                    </td>
                  ))}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    );
  }

  if (block.type === 'heading') {
    return (
      <div className="py-3" style={indentStyle}>
        <RichText content={block.content} className="text-2xl font-bold leading-tight text-slate-900" />
      </div>
    );
  }

  if (block.type === 'heading2') {
    return (
      <div className="py-2.5" style={indentStyle}>
        <RichText content={block.content} className="text-xl font-bold leading-tight text-slate-900" />
      </div>
    );
  }

  if (block.type === 'heading3') {
    return (
      <div className="py-2" style={indentStyle}>
        <RichText content={block.content} className="text-lg font-semibold leading-snug text-slate-900" />
      </div>
    );
  }

  if (block.type === 'bulletList') {
    const level = depth;
    const bullet = bulletMarkerForLevel(level).trim();
    return (
      <div style={indentStyle}>
        <div className="flex items-start gap-2 py-0.5">
          <span className="mt-1 min-w-[1.25rem] shrink-0 text-center text-[15px] leading-7 text-slate-800" aria-hidden>
            {bullet}
          </span>
          <RichText
            content={listItemContent(block.content)}
            className="min-w-0 flex-1 text-[15px] leading-7 text-slate-800"
          />
        </div>
        {childBlocks.length > 0 ? (
          <div className="space-y-0">
            {childBlocks.map((child) => renderChildBlock?.(child))}
          </div>
        ) : null}
      </div>
    );
  }

  if (block.type === 'numberedList') {
    const displayNum = typeof block.content?.number === 'number' ? block.content.number : 1;
    return (
      <div style={indentStyle}>
        <div className="flex items-start gap-2 py-0.5">
          <span className="mt-1 min-w-[1.25rem] shrink-0 text-right text-[15px] leading-7 text-slate-500" aria-hidden>
            {displayNum}.
          </span>
          <RichText
            content={listItemContent(block.content)}
            className="min-w-0 flex-1 text-[15px] leading-7 text-slate-800"
          />
        </div>
        {childBlocks.length > 0 ? (
          <div className="space-y-0">
            {childBlocks.map((child) => renderChildBlock?.(child))}
          </div>
        ) : null}
      </div>
    );
  }

  if (block.type === 'todo') {
    const checked = !!block.content?.checked;
    return (
      <div
        className={`flex items-start gap-3 ${isInsideToggle || isBorderlessInlineBlock ? 'py-1.5' : `${rootBlockShell} py-2`}`}
        style={indentStyle}
      >
        <span
          className={`mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded border-2 ${
            checked ? 'border-blue-500 bg-blue-500 text-white' : 'border-slate-300 bg-white'
          }`}
        >
          {checked ? <Check className="h-3 w-3" /> : null}
        </span>
        <RichText
          content={block.content}
          className={`text-[15px] leading-7 ${checked ? 'text-slate-400 line-through' : 'text-slate-800'}`}
        />
      </div>
    );
  }

  if (block.type === 'callout') {
    const icon = typeof block.content?.icon === 'string' && block.content.icon.trim()
      ? block.content.icon
      : '💡';
    return (
      <div className="rounded-xl border border-amber-200 bg-amber-50/60 px-3 py-2" style={indentStyle}>
        <div className="mb-1 text-sm">{icon}</div>
        <RichText content={block.content} className="text-[15px] leading-7 text-slate-800" />
      </div>
    );
  }

  if (block.type === 'quote') {
    return (
      <div className="border-l-[3px] border-slate-300 pl-3 py-0.5" style={indentStyle}>
        <RichText content={block.content} className="text-[15px] leading-7 text-slate-600 italic" />
      </div>
    );
  }

  if (block.type === 'code') {
    const text = typeof block.content?.text === 'string' ? block.content.text : '';
    const language = readCodeLanguage(block.content);
    return (
      <div className="rounded-xl border border-slate-200 bg-slate-950 px-4 py-3" style={indentStyle}>
        <div className="mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-400">
          {codeLanguageLabel(language)}
        </div>
        <pre className="overflow-x-auto whitespace-pre-wrap font-mono text-[13px] leading-6 text-slate-100">{text}</pre>
      </div>
    );
  }

  if (block.type === 'image') {
    const url = typeof block.content?.url === 'string' ? block.content.url.trim() : '';
    if (!url) return null;
    const caption = typeof block.content?.caption === 'string' ? block.content.caption.trim() : '';
    const imageWidthPercent = readImageWidthPercent(block.content);
    const imageAlign = readImageAlign(block.content);
    return (
      <div className="py-2" style={indentStyle}>
        <div
          className={`${imageBlockAlignClass(imageAlign)}`}
          style={imageFrameWidthStyle(imageWidthPercent)}
        >
          <div className="overflow-hidden rounded-xl border border-slate-200 bg-slate-50">
            <img src={url} alt={caption || ''} className="max-h-96 w-full object-contain" />
          </div>
          {caption ? (
            <p className={`mt-1.5 text-[12px] text-slate-500 ${imageCaptionAlignClass(imageAlign)}`}>{caption}</p>
          ) : null}
        </div>
      </div>
    );
  }

  if (block.type === 'video') {
    const embed = resolveVideoEmbedContent(block.content);
    if (!embed) return null;
    return (
      <div className={isInsideToggle ? 'py-1.5' : `${rootBlockShell} py-2`} style={indentStyle}>
        <p className="mb-2 text-[11px] font-medium text-slate-400">
          {videoProviderLabel(embed.provider)} 영상
        </p>
        <VideoEmbedFrame embedUrl={embed.embedUrl} title={`${videoProviderLabel(embed.provider)} 영상`} />
      </div>
    );
  }

  if (block.type === 'page') {
    const pageId = typeof block.content?.page_document_id === 'string' ? block.content.page_document_id : '';
    const title =
      (typeof block.content?.title === 'string' && block.content.title.trim())
        ? block.content.title
        : '문서';
    const shareToken = pageId ? publicPages[pageId] : undefined;
    const inner = (
      <div className="flex items-center gap-3 rounded-xl border border-slate-200 bg-white px-4 py-3 shadow-sm">
        <FileText className="h-4 w-4 shrink-0 text-blue-600" />
        <div className="min-w-0 flex-1">
          <p className="truncate text-[14px] font-semibold text-slate-800">{title}</p>
          <p className="mt-0.5 text-[11px] text-slate-400">
            {shareToken ? '공개 하위 문서' : '비공개 문서'}
          </p>
        </div>
      </div>
    );
    return (
      <div className="py-1.5" style={indentStyle}>
        {shareToken ? (
          <Link href={`/note/p/${shareToken}`} className="block transition hover:opacity-90">
            {inner}
          </Link>
        ) : inner}
      </div>
    );
  }

  if (block.type === 'columnList') {
    const columns = [...childBlocks]
      .filter((child) => child.type === 'column')
      .sort((left, right) => left.order_index - right.order_index);
    return (
      <div className={`overflow-x-auto py-2 ${rootBlockShell}`} style={indentStyle}>
        <div className="flex w-full items-start gap-3">
          {columns.map((column) => {
            const columnChildren = lookupChildBlocks?.(column.id) ?? [];
            return (
              <div
                key={column.id}
                className="min-w-0 flex-1 rounded-md border border-slate-200/80 bg-white px-2 py-1.5"
              >
                {columnChildren.length > 0 ? (
                  <div className="space-y-0">
                    {columnChildren.map((child) => renderChildBlock?.(child))}
                  </div>
                ) : (
                  <div className="min-h-[30px]" aria-hidden />
                )}
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  if (block.type === 'toggle') {
    return (
      <PublicToggleBlock
        block={block}
        publicPages={publicPages}
        indentStyle={indentStyle}
        childBlocks={childBlocks}
        renderChildBlock={renderChildBlock}
        isInsideToggle={isInsideToggle}
      />
    );
  }

  return (
    <div
      className={isInsideToggle || isBorderlessInlineBlock ? 'py-0.5' : `${rootBlockShell} py-2`}
      style={indentStyle}
    >
      <RichText content={block.content} className="text-[15px] leading-7 text-slate-800" />
    </div>
  );
}

function PublicToggleBlock({
  block,
  publicPages,
  indentStyle,
  childBlocks = [],
  renderChildBlock,
  isInsideToggle = false,
}: {
  block: PublicNoteBlock;
  publicPages: Record<string, string>;
  indentStyle?: React.CSSProperties;
  childBlocks?: PublicNoteBlock[];
  renderChildBlock?: (child: PublicNoteBlock) => React.ReactNode;
  isInsideToggle?: boolean;
}) {
  const [open, setOpen] = useState(!block.content?.collapsed);
  const title = typeof block.content?.title === 'string'
    ? block.content.title
    : (typeof block.content?.text === 'string' ? block.content.text : '');
  const rawImages = block.content?.images;
  const images = Array.isArray(rawImages)
    ? rawImages.map((url) => (typeof url === 'string' ? url.trim() : '')).filter(Boolean)
    : [];

  return (
    <div
      className={
        isInsideToggle
          ? 'py-0.5'
          : 'rounded-lg border border-slate-200 bg-white px-3 py-2'
      }
      style={indentStyle}
    >
      <button
        type="button"
        className="flex w-full items-center gap-2 text-left"
        onClick={() => setOpen((v) => !v)}
      >
        <ChevronDown className={`h-4 w-4 shrink-0 text-slate-500 transition-transform ${open ? '' : '-rotate-90'}`} />
        <span className="text-[15px] font-semibold leading-6 text-slate-800">{title || '토글'}</span>
      </button>
      {open && (
        <div className="pl-6">
          {childBlocks.length > 0 && (
            <div className="space-y-0">
              {childBlocks.map((child) => renderChildBlock?.(child))}
            </div>
          )}
          {images.length > 0 && (
            <div className="mt-3 space-y-2 border-t border-slate-100 pt-3">
              {images.map((url) => (
                <div key={url} className="overflow-hidden rounded-lg border border-slate-100 bg-slate-50 p-2">
                  <div className="mb-1 flex items-center gap-2 text-[11px] text-slate-400">
                    <ImageIcon className="h-3.5 w-3.5" />
                    이미지
                  </div>
                  <img src={url} alt="" className="max-h-56 w-full object-contain" />
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export function PublicNoteView({
  document,
  blocks,
  publicPages,
}: {
  document: PublicNoteDocument;
  blocks: PublicNoteBlock[];
  publicPages: Record<string, string>;
}) {
  const childrenByParentBlock = useMemo(() => buildChildrenByParentBlock(blocks), [blocks]);
  const rootBlocks = useMemo(() => sortRootBlocks(blocks), [blocks]);

  const renderPublicBlock = (block: PublicNoteBlock, insideToggle = false): React.ReactNode => (
    <PublicBlock
      key={block.id}
      block={block}
      publicPages={publicPages}
      isInsideToggle={insideToggle}
      childBlocks={childrenByParentBlock.get(block.id) ?? []}
      lookupChildBlocks={(parentId) => childrenByParentBlock.get(parentId) ?? []}
      renderChildBlock={(child) => renderPublicBlock(child, true)}
    />
  );

  return (
    <div className="min-h-screen bg-white">
      <div className="border-b border-slate-100 bg-slate-50/80">
        <div className="mx-auto flex max-w-3xl items-center justify-between px-4 py-3 md:px-8">
          <span className="rounded-md bg-slate-900 px-2 py-1 text-[10px] font-bold uppercase tracking-widest text-white">
            Shared Note
          </span>
          <span className="text-[11px] text-slate-400">읽기 전용</span>
        </div>
      </div>
      <article className="mx-auto max-w-3xl px-4 py-10 md:px-8">
        <h1 className="mb-8 text-[36px] font-extrabold leading-[1.08] tracking-tight text-slate-950 md:text-[44px]">
          {document.title}
        </h1>
        <div className="space-y-0.5">
          {rootBlocks.map((block) => renderPublicBlock(block))}
        </div>
      </article>
      <style jsx global>{`
        .public-note-rich p {
          margin: 0;
        }
        .public-note-rich a {
          color: rgb(37 99 235);
          text-decoration: underline;
          text-underline-offset: 2px;
        }
        .public-note-rich u {
          text-decoration: underline;
          text-underline-offset: 2px;
        }
        .public-note-rich code {
          border-radius: 0.375rem;
          background: rgb(241 245 249);
          padding: 0.1rem 0.25rem;
          font-size: 0.92em;
        }
        .public-note-rich mark {
          border-radius: 0.125rem;
          padding: 0.05rem 0.1rem;
        }
        .public-note-rich h1,
        .public-note-rich h2,
        .public-note-rich h3 {
          margin: 0;
          font-weight: 700;
        }
      `}</style>
    </div>
  );
}

'use client';

import Image from 'next/image';
import { motion, useReducedMotion } from 'framer-motion';
import { useEffect, useState } from 'react';
import type { HomeMediaItem } from '../../data/home-media';
import { homePhotoGrade } from '../../lib/ui-classes';
import { BrandOverlay } from './brand-overlay';
import { GradientVisual } from './gradient-visual';

type MediaRendererProps = {
  media: HomeMediaItem;
  className?: string;
  showLabel?: boolean;
  intensity?: 'soft' | 'bold' | 'photo';
  priority?: boolean;
  sizes?: string;
  animateZoom?: boolean;
  /** Home 등: 로드 실패 시 gradient/SVG placeholder 대신 빈 실사 영역 */
  strictPhoto?: boolean;
  objectFit?: 'cover' | 'contain';
};

export function MediaRenderer({
  media,
  className = '',
  showLabel = false,
  intensity = 'bold',
  priority = false,
  sizes = '(max-width: 768px) 100vw, 50vw',
  animateZoom = false,
  strictPhoto = false,
  objectFit = 'cover',
}: MediaRendererProps) {
  const reducedMotion = useReducedMotion();
  const primarySrc = media.src;
  const [useImage, setUseImage] = useState(Boolean(primarySrc));
  const [imgSrc, setImgSrc] = useState(primarySrc ?? '');

  useEffect(() => {
    setUseImage(Boolean(primarySrc));
    setImgSrc(primarySrc ?? '');
  }, [primarySrc]);

  const handleError = () => {
    // A generic field fallback is intentionally not used for marketing cards:
    // it is too pale and reads as an empty panel when a photo URL is stale.
    // Fall back directly to the branded visual so a failed asset can never
    // leave a blank white card behind.
    setUseImage(false);
  };

  if (!useImage || !imgSrc) {
    return (
      <GradientVisual
        media={media}
        className={className}
        showLabel={showLabel}
        intensity={intensity === 'photo' ? 'soft' : intensity}
      />
    );
  }

  const fitClass = objectFit === 'contain' ? 'object-contain' : homePhotoGrade;

  const imageNode = (
    <Image
      src={imgSrc}
      alt={media.alt}
      fill
      sizes={sizes}
      priority={priority}
      quality={priority ? 92 : 88}
      className={intensity === 'photo' ? fitClass : 'object-cover'}
      style={objectFit === 'cover' && media.objectPosition ? { objectPosition: media.objectPosition } : undefined}
      onError={handleError}
    />
  );

  return (
    <div className={`relative h-full w-full overflow-hidden bg-slate-200 ${className}`}>
      {animateZoom && !reducedMotion ? (
        <motion.div
          className="absolute inset-0"
          animate={{ scale: [1, 1.06, 1] }}
          transition={{ duration: 16, repeat: Infinity, ease: 'easeInOut' }}
        >
          {imageNode}
        </motion.div>
      ) : (
        imageNode
      )}
      <BrandOverlay tone={media.tone} intensity={intensity} />
      {showLabel && media.label ? (
        <figcaption className="pointer-events-none absolute bottom-3 left-3 z-10 rounded-lg border border-white/25 bg-white/10 px-2.5 py-1 text-[11px] font-medium text-white backdrop-blur-md">
          {media.label}
        </figcaption>
      ) : null}
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { getSupabaseBrowserClient } from '@/app/lib/supabase/browser';
import { devLogger } from '@/app/lib/logging/devLogger';
import { 
  Package, Search, Loader2, 
  Image as ImageIcon, CheckSquare, ListOrdered, Calendar, History, ExternalLink, UserCircle2
} from 'lucide-react';

interface InventoryItem {
  id: string;
  name: string;
  category: string;
  image?: string | null;
  quantity: number;
  updated_at: string;
  simple_desc?: string | null;
  key_points?: string | null;
  usage_examples?: string | null;
}

interface InventoryLog {
  id: string;
  created_at: string;
  type: 'in' | 'out' | string;
  content: string;
}

// URL 링크 변환 헬퍼
const renderTextWithLinks = (text: string) => {
  if (!text) return "";
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.split(urlRegex).map((part, i) => {
    if (part.match(urlRegex)) {
      return (
        <a key={i} href={part} target="_blank" rel="noopener noreferrer" className="text-blue-400 underline hover:text-blue-300 inline-flex items-center gap-0.5 break-all cursor-pointer z-50 relative" onClick={(e) => e.stopPropagation()}>
          {part} <ExternalLink size={10} />
        </a>
      );
    }
    return part;
  });
};

export default function TeacherInventoryPage() {
  const [supabase] = useState(() => (typeof window !== 'undefined' ? getSupabaseBrowserClient() : null));
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [logs, setLogs] = useState<InventoryLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [userName, setUserName] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [detailItem, setDetailItem] = useState<InventoryItem | null>(null);
  const [fetchError, setFetchError] = useState<string | null>(null);

  const fetchMyData = useCallback(async () => {
    if (!supabase) return;
    setLoading(true);
    setFetchError(null);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const user = session?.user;

      if (!user) {
        setFetchError('로그인이 필요합니다.');
        setLoading(false);
        return;
      }

      // 2. 유저 이름 가져오기
      const { data: userData } = await supabase.from('users').select('name').eq('id', user.id).single();
      if (userData) setUserName(userData.name);

      // 3. 내 교구 리스트 가져오기
      const { data: invData } = await supabase
        .from('inventory')
        .select('*')
        .eq('user_id', user.id)
        .order('name', { ascending: true });

      // 4. 내 활동 로그 가져오기
      const { data: logData } = await supabase
        .from('inventory_logs')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })
        .limit(30);

      if (invData) setInventory(invData as InventoryItem[]);
      if (logData) setLogs(logData as InventoryLog[]);
    } catch (err) {
      devLogger.error(err);
      setFetchError('데이터를 불러오지 못했습니다.');
    } finally {
      setLoading(false);
    }
  }, [supabase]);

  useEffect(() => {
     
    void fetchMyData();
  }, [fetchMyData]);

  // 검색 필터링
  const filteredInventory = inventory.filter(item => 
    (item.name ?? '').includes(searchQuery) || (item.category ?? '').includes(searchQuery)
  );

  return (
    <div className="flex flex-col h-screen bg-[#F8FAFC] font-sans text-slate-900 overflow-hidden">
      
      {/* --- Header --- */}
      <header className="shrink-0 z-30 sticky top-0 bg-white/80 backdrop-blur-md border-b border-slate-200">
        <div className="h-16 px-6 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-full bg-indigo-50 flex items-center justify-center text-indigo-600 border border-indigo-100">
                    <UserCircle2 size={20} />
                </div>
                <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">My Inventory</p>
                    <h1 className="text-sm font-black text-slate-800">{userName ? `${userName} 선생님` : '선생님'}</h1>
                </div>
            </div>
            <div className="flex items-center gap-3">
                <div className="relative hidden md:block">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                    <input 
                        type="text" 
                        placeholder="교구 검색..." 
                        className="pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-100 transition-all w-48"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                    />
                </div>
                <div className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-xs font-black shadow-lg shadow-slate-200">
                    Total: {inventory.length}
                </div>
            </div>
        </div>
        {/* 모바일 전용 검색바 */}
        <div className="md:hidden px-4 pb-3">
            <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                <input
                    type="text"
                    placeholder="교구 이름 또는 카테고리 검색..."
                    className="w-full pl-9 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-100 transition-all"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                />
            </div>
        </div>
      </header>

      {/* --- Main Grid (Scrollable) --- */}
      <main className="flex-1 overflow-y-auto p-6 min-h-0 bg-[#F8FAFC]">
        {fetchError ? (
            <div className="h-full flex flex-col items-center justify-center gap-3">
                <p className="text-sm font-bold text-slate-500">{fetchError}</p>
                <button type="button" onClick={fetchMyData} className="text-indigo-600 text-xs font-black hover:underline">
                  다시 시도
                </button>
            </div>
        ) : loading ? (
            <div className="h-full flex flex-col items-center justify-center gap-3">
                <Loader2 className="animate-spin text-indigo-500" size={32} />
                <p className="text-xs font-bold text-slate-400">데이터를 불러오는 중입니다...</p>
            </div>
        ) : filteredInventory.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 opacity-60">
                <Package size={64} strokeWidth={1} className="mb-4" />
                <p className="text-lg font-black text-slate-400">보유 중인 교구가 없습니다.</p>
                <p className="text-xs font-bold mt-1">관리자에게 교구 배부를 요청하세요.</p>
            </div>
        ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-5 pb-20">
                {filteredInventory.map((item) => (
                    <div
                        key={item.id}
                        role="button"
                        tabIndex={0}
                        className="bg-white rounded-[28px] shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 overflow-hidden border border-slate-200 cursor-pointer group"
                        onClick={() => setDetailItem(item)}
                        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setDetailItem(item); } }}
                    >
                        {/* Image Section */}
                        <div className="h-40 relative overflow-hidden bg-slate-100 flex items-center justify-center">
                            {item.image ? <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" /> : <ImageIcon size={32} className="text-slate-300"/>}
                            <div className="absolute top-3 left-3">
                                <span className="bg-black/60 text-white text-[10px] font-black px-2.5 py-1 rounded-full backdrop-blur-md uppercase tracking-wider shadow-sm">
                                    {item.category}
                                </span>
                            </div>
                        </div>

                        {/* Info Section */}
                        <div className="p-5">
                            <div className="mb-4">
                                <h3 className="text-lg font-black text-slate-800 truncate leading-tight">{item.name}</h3>
                                <div className="flex items-center gap-1.5 mt-1 text-slate-400 font-bold text-[10px] uppercase tracking-tight">
                                    <Calendar size={12} />
                                    {new Date(item.updated_at).toLocaleDateString()} 수령
                                </div>
                            </div>

                            {/* Read-Only Quantity Display */}
                            <div className="bg-slate-50 rounded-2xl p-3 border border-slate-100 flex justify-between items-center group-hover:border-indigo-100 transition-colors">
                                <span className="text-[10px] font-bold text-slate-400 uppercase">보유 수량</span>
                                <span className="text-2xl font-black text-indigo-600">{item.quantity} <span className="text-sm font-bold text-slate-400">ea</span></span>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        )}
      </main>

      {/* --- Logs Section (Fixed Bottom) --- */}
      <div className="h-48 border-t border-slate-200 bg-white flex flex-col shrink-0 z-20">
        <div className="px-6 py-3 border-b border-slate-100 flex items-center gap-2 bg-slate-50/50">
            <History size={16} className="text-slate-400" />
            <span className="text-[11px] font-black text-slate-500 uppercase tracking-widest">나의 활동 히스토리</span>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar bg-[#FAFAFA]">
            {logs.length === 0 ? (
                <p className="text-center text-xs text-slate-400 py-6 italic">아직 기록된 활동이 없습니다.</p>
            ) : (
                logs.map((log) => (
                    <div key={log.id} className="flex items-start gap-3 text-sm px-2 py-1">
                        <span className="text-slate-400 text-[10px] font-bold mt-0.5 whitespace-nowrap min-w-[70px]">
                            {new Date(log.created_at).toLocaleString('ko-KR', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })}
                        </span>
                        <span className={`font-bold ${log.type === 'in' ? 'text-indigo-600' : log.type === 'out' ? 'text-rose-500' : 'text-slate-700'}`}>
                            {log.content}
                        </span>
                    </div>
                ))
            )}
        </div>
      </div>

      {/* --- Detail Modal (Same Design as Admin) --- */}
      {detailItem && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-sm animate-in fade-in" onClick={() => setDetailItem(null)}>
          <div className="w-full max-w-md bg-[#121212] rounded-[32px] overflow-hidden shadow-2xl animate-in zoom-in-95 text-white border border-slate-800" onClick={e => e.stopPropagation()}>
            {/* Modal Header */}
            <div className="p-8 pb-6 border-b border-slate-800 flex gap-6 items-center">
                <div className="w-20 h-20 rounded-[20px] bg-slate-800 overflow-hidden shrink-0 flex items-center justify-center border border-slate-700">
                    {detailItem.image ? <img src={detailItem.image} className="w-full h-full object-cover" /> : <Package size={32} className="text-slate-600"/>}
                </div>
                <div className="flex-1 min-w-0">
                    <span className="text-[11px] font-black text-indigo-400 uppercase tracking-[0.2em]">{detailItem.category}</span>
                    <h2 className="text-3xl font-black mt-1 leading-none">{detailItem.name}</h2>
                    <p className="text-sm text-slate-400 mt-3 font-medium leading-snug">{detailItem.simple_desc || '기본 설명이 등록되지 않았습니다.'}</p>
                </div>
            </div>

            {/* Modal Body */}
            <div className="p-8 space-y-8 max-h-[50vh] overflow-y-auto custom-scrollbar">
                {/* Key Points */}
                <div className="bg-[#1a1a1a] p-5 rounded-2xl border border-slate-800">
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase mb-3 flex items-center gap-2 tracking-widest">
                        <CheckSquare size={14} /> 핵심 포인트
