  start_at: string;
  session_type: string;
  status: string;
  created_by?: string | null;
  memo?: string | null;
  group_id?: string | null;
  students_text?: string;
  photo_url?: string[];
  file_url?: string[];
  feedback_fields?: FeedbackFields;
}

interface PreviousLessonPlan {
  sessionId: string;
  start_at: string;
  content: string;
}

const LESSON_PLAN_DEFAULT_TEMPLATE = `2026.00.00.(요일) 00:00 ~ 00:00 - n회차

강사명 : 
수업 장소 : 
사용 교구: 

