const SESSION_FILES_BUCKET = 'session-files';

/** Supabase Storage 공개/서명 URL에서 `session-files` 버킷 기준 객체 경로 */
function sessionFilesObjectPathFromPublicUrl(fileUrl: string): string | null {
  try {
    const u = new URL(fileUrl.trim());
    const m = u.pathname.match(
      new RegExp(`^/storage/v1/object/(?:public|sign|authenticated)/${SESSION_FILES_BUCKET}/(.+)$`),
    );
    if (!m?.[1]) return null;
    return m[1]
      .split('/')
      .map((seg) => {
        try {
          return decodeURIComponent(seg);
        } catch {
          return seg;
        }
      })
      .join('/');
  } catch {
    return null;
  }
}

function MyClassesContent() {
  const [supabase] = useState(() => (typeof window !== 'undefined' ? getSupabaseBrowserClient() : null));
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedEvent, setSelectedEvent] = useState<Session | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [feedbackFields, setFeedbackFields] = useState<FeedbackFields>({});
  const [uploading, setUploading] = useState(false);
  const [photoUrls, setPhotoUrls] = useState<string[]>([]);
  const [fileUrls, setFileUrls] = useState<string[]>([]);
  const [currentDate, setCurrentDate] = useState<Date | null>(null);
  const [isLessonPlanModalOpen, setIsLessonPlanModalOpen] = useState(false);
  const [lessonPlanContent, setLessonPlanContent] = useState(LESSON_PLAN_DEFAULT_TEMPLATE);
  const [lessonPlanSaving, setLessonPlanSaving] = useState(false);
  const [currentSessionLessonPlanId, setCurrentSessionLessonPlanId] = useState<string | null>(null);
  const [previousPlans, setPreviousPlans] = useState<PreviousLessonPlan[]>([]);
  const [previousPlansExpandedId, setPreviousPlansExpandedId] = useState<string | null>(null);
  const [scheduleError, setScheduleError] = useState<string | null>(null);
  /** 일정 API 기준 로그인 사용자 — `created_by`와 다르면 보조로 들어간 수업 */
  const [scheduleUserId, setScheduleUserId] = useState<string | null>(null);

  const getBaseTitle = (title: string): string => {
    const original = title;
    const cleaned = title
      .replace(/^\d+\/\d+\s+/i, '')
      .replace(/\s*[-_/]\s*\d+회차$/i, '')
      .replace(/\s+\d+회차$/i, '')
      .replace(/\s*[-_/]\s*\d+회$/i, '')
      .replace(/\s+\d+회$/i, '')
      .replace(/\s*[-_/]\s*\d+차$/i, '')
      .replace(/\s+\d+차$/i, '')
      .replace(/\s*[-_/]\s*\d+$/i, '')
      .replace(/\s+\d+$/i, '')
      .replace(/\d+$/, '')
      .replace(/\s*\(\d+\)$/i, '')
      .replace(/\s*\(\d{4}-\d{2}-\d{2}\)$/i, '')
      .replace(/\s*\d{4}-\d{2}-\d{2}$/i, '')
      .trim();
    return cleaned || original;
  };

  const isToday = (dateString: string) => {
    const today = new Date();
    const target = new Date(dateString);
    return today.getFullYear() === target.getFullYear() &&
           today.getMonth() === target.getMonth() &&
           today.getDate() === target.getDate();
  };

  const getWeekRange = (date: Date) => {
    // 사용자 로컬 타임존 기준으로 주간을 계산하면,
    // start_at 경계(특히 자정 근처)에서 특정 세션만 "다른 주에 남는" 문제가 생길 수 있습니다.
    // 따라서 'KST 달력' 기준으로 주간 범위를 계산하고, 결과는 DB 쿼리용 UTC ISO로 변환합니다.
    const KST_OFFSET_MS = 9 * 60 * 60 * 1000;

    // 1) 입력 date를 "UTC millis"로 정규화 후, KST로 치환해서 KST 달력 값을 얻습니다.
    const utcMillis = date.getTime() + date.getTimezoneOffset() * 60 * 1000;
    const kstMillis = utcMillis + KST_OFFSET_MS;
    const kstDate = new Date(kstMillis);

    const year = kstDate.getUTCFullYear();
    const month = kstDate.getUTCMonth();
    const dayOfMonth = kstDate.getUTCDate();
    const dayOfWeek = kstDate.getUTCDay(); // 0(Sun) ~ 6(Sat)

    // KST 달력 기준 월요일 날짜(일~월 보정 포함)
    const mondayDayOfMonth = dayOfMonth - dayOfWeek + (dayOfWeek === 0 ? -6 : 1);

    // KST 자정(00:00 KST)은 UTC로는 -9시간입니다.
    const mondayUtcMillis = Date.UTC(year, month, mondayDayOfMonth) - KST_OFFSET_MS;
    const sundayUtcMillis =
      Date.UTC(year, month, mondayDayOfMonth + 6) - KST_OFFSET_MS +
      (23 * 60 * 60 * 1000 + 59 * 60 * 1000 + 59 * 1000 + 999);

    const monday = new Date(mondayUtcMillis);
    const sunday = new Date(sundayUtcMillis);

    return { monday, sunday };
  };

  const getMySchedule = useCallback(async () => {
    if (!supabase) return;
    setLoading(true);
    setScheduleError(null);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.user) return;
      setScheduleUserId(session.user.id);

      if (!currentDate) return;
      const { monday, sunday } = getWeekRange(new Date(currentDate));

      const res = await fetch(
        `/api/teacher/my-schedule?from=${monday.toISOString()}&to=${sunday.toISOString()}`
      );
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = await res.json();
      setSessions(json.data || []);
    } catch (err) {
      devLogger.error(err);
      setScheduleError('일정을 불러오지 못했습니다.');
    } finally {
      setLoading(false);
    }
  }, [supabase, currentDate]);

  useEffect(() => {
    setCurrentDate((prev) => prev ?? new Date());
  }, []);

  useEffect(() => { getMySchedule(); }, [getMySchedule]);

  // 주간을 이동하면(이번주/지난주 데이터가 바뀌면) 모달의 선택값/입력값이
  // 이전 주 세션 기준으로 남아 혼동되는 케이스가 있습니다.
  // 특정 계정에서만 체감될 수 있지만, 상태 초기화로 방지합니다.
  useEffect(() => {
    if (uploading) return;

    setIsModalOpen(false);
    setSelectedEvent(null);
    setFeedbackFields({});
    setPhotoUrls([]);
    setFileUrls([]);

    setIsLessonPlanModalOpen(false);
    setLessonPlanContent(LESSON_PLAN_DEFAULT_TEMPLATE);
    setCurrentSessionLessonPlanId(null);
    setPreviousPlans([]);
    setPreviousPlansExpandedId(null);
  }, [currentDate]);

  const handleItemClick = (session: Session) => {
    if (session.status === 'postponed') {
      toast.info(
        '이 시간대는 연기 처리된 기록입니다. 같은 수업은 일정이 밀린 날짜에 표시되니, 주간 일정에서 해당 날짜를 확인해 주세요.',
      );
      return;
    }
    if (session.status === 'cancelled') {
      toast.info('취소된 수업입니다.');
      return;
    }

    const feedbackFieldsKeyCount = session.feedback_fields ? Object.keys(session.feedback_fields).length : 0;
    const nextFeedbackFields: FeedbackFields =
      session.feedback_fields && feedbackFieldsKeyCount > 0
        ? session.feedback_fields
        : session.students_text
          ? parseTemplateToFields(session.students_text)
          : {};
    setSelectedEvent(session);

    const isCompleted = session.status === 'finished' || session.status === 'verified';
    // opened 세션(아직 작성 전)에 복제/생성 과정에서 students_text/첨부가 섞여 들어오면
    // 교사 화면에서 "이미 작성된 것처럼" 보일 수 있습니다.
    // 그래서 finished/verified일 때만 기존 피드백을 보여주고, 그 외에는 입력을 비웁니다.
    if (!isCompleted) {
      setFeedbackFields({});
      setPhotoUrls([]);
      setFileUrls([]);
      setIsModalOpen(true);
      return;
    }

    const urls = Array.isArray(session.file_url) ? session.file_url : [];
    const isCenterSession =
      isCenterSessionType(session.session_type);
    const centerUrlsForModal = isCenterSession ? urls.slice(0, 2) : urls;

    let fieldsForModal: FeedbackFields = nextFeedbackFields;
    if (isCenterSession && centerUrlsForModal.length > 0) {
      const names = nextFeedbackFields.center_document_names;
      let namesForAlign: string[] | undefined;
      namesForAlign = Array.isArray(names) ? names.slice(0, 2) : undefined;
      fieldsForModal = {
        ...nextFeedbackFields,
        center_document_names: alignCenterDocumentNamesWithUrls(centerUrlsForModal, namesForAlign),
      };
    } else if (!isCenterSession) {
      const { center_document_names: _c, ...rest } = nextFeedbackFields as FeedbackFields & {
        center_document_names?: string[];
      };
      fieldsForModal = rest;
    }

    setFeedbackFields(fieldsForModal);
    setPhotoUrls(Array.isArray(session.photo_url) ? session.photo_url : []);
    setFileUrls(isCenterSession ? centerUrlsForModal : urls);
    setIsModalOpen(true);
  };

  const handleCompleteSession = async () => {
    if (!supabase || !selectedEvent || uploading) return;

    const sessionStart = new Date(selectedEvent.start_at);
    const today = new Date();
    sessionStart.setHours(0, 0, 0, 0);
    today.setHours(0, 0, 0, 0);

    if (sessionStart > today) {
      return toast.error('수업일이 아직 지나지 않았습니다. 수업일 이후에 완료 처리해 주세요.');
    }
    
    const isCenterType = isCenterSessionType(selectedEvent.session_type);

    if (isCenterType) {
      if (fileUrls.length === 0) {
        return toast.error('파일을 최소 1개 업로드해주세요.');
      }
    } else {
      // 개인 수업: 필수 필드 체크
      const missingFields = FEEDBACK_TEXT_FIELD_KEYS.filter((field) => {
        const v = feedbackFields[field];
        return typeof v !== 'string' || v.trim().length < 5;
      });
      
      if (missingFields.length > 0) {
        const fieldNames: Record<string, string> = {
          main_activity: '오늘 수업의 주요 활동',
          strengths: '강점 및 긍정적인 부분',
          improvements: '개선이 필요한 부분 및 피드백',
          next_goals: '다음 수업 목표 및 계획',
          condition_notes: '특이사항 및 시작/종료 시간'
        };
        const missingFieldNames = missingFields.map((f) => fieldNames[f]).join(', ');
        return toast.error(`다음 필드를 작성해주세요: ${missingFieldNames}`);
      }
    }

    setUploading(true);
    try {
      const res = await fetch('/api/teacher/session-feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          sessionId: selectedEvent.id,
          feedbackFields,
          photoUrls,
          fileUrls:
            isCenterType && fileUrls.length > 0 ? [fileUrls[fileUrls.length - 1]!] : fileUrls,
        }),
      });
      const payload = (await res.json().catch(() => ({}))) as { error?: string; ok?: boolean };
      if (!res.ok) {
        throw new Error(payload.error || '저장에 실패했습니다.');
      }

      toast.success('성공적으로 저장되었습니다.');

      setIsModalOpen(false);
      getMySchedule();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      toast.error('저장 실패: ' + msg);
    } finally {
      setUploading(false);
    }
  };

  const handleResetStatus = async () => {
    if (!selectedEvent || !confirm('초기화하시겠습니까? (작성된 피드백이 삭제됩니다)')) return;
    setUploading(true);
    try {
      const res = await fetch('/api/teacher/session-reset', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ sessionId: selectedEvent.id }),
      });
      const payload = (await res.json().catch(() => ({}))) as { error?: string };
      if (!res.ok) throw new Error(payload.error || '초기화에 실패했습니다.');
      setIsModalOpen(false);
      getMySchedule();
    } catch (err: unknown) {
      toast.error('초기화 실패: ' + (err instanceof Error ? err.message : String(err)));
    } finally {
      setUploading(false);
    }
  };

  const uploadFile = async (file: File, bucket: string) => {
    if (!supabase || !selectedEvent) return null;
    setUploading(true);
    try {
      const displayName =
        file.name.normalize('NFC').trim().replace(/[/\\]/g, '_').slice(0, 300) || 'file';
      const rawName = file.name.normalize('NFC').trim();
      const lastDot = rawName.lastIndexOf('.');
      const basePart = lastDot > 0 ? rawName.slice(0, lastDot) : rawName;
      let ext =
        lastDot > 0 && lastDot < rawName.length - 1
          ? rawName.slice(lastDot).replace(/[^.a-zA-Z0-9]/g, '')
          : '';
      const sanitizedBase = basePart
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-zA-Z0-9_-]/g, '_')
        .replace(/_+/g, '_')
        .replace(/^_|_$/g, '');
      const safeBase = sanitizedBase.length > 0 ? sanitizedBase : 'file';

      let uploadFileBody: File = file;
      let contentType: string | undefined;
      // 이미지면 업로드 전 자동 리사이즈·압축 (원본 수 MB → 보통 100~400KB, 목표 ≤1.5MB)
      const shouldCompressImage =
        isImageFile(file) && (bucket === 'session-photos' || bucket === SESSION_FILES_BUCKET);
      if (shouldCompressImage) {
        uploadFileBody = await compressImageForUpload(file, { maxBytes: SESSION_PHOTO_MAX_BYTES });
        if (uploadFileBody.type === 'image/webp') {
          ext = '.webp';
          contentType = 'image/webp';
        } else if (uploadFileBody.type === 'image/jpeg') {
          ext = '.jpg';
          contentType = 'image/jpeg';
        } else {
          contentType = uploadFileBody.type || undefined;
        }
      } else if (bucket === SESSION_FILES_BUCKET) {
        // 워드/PPT/엑셀/한글(hwpx) 문서 안 임베드 사진 리사이즈·압축
        uploadFileBody = await compressDocumentEmbeddedImages(file);
        contentType = uploadFileBody.type || undefined;
      }

      const safeFileName = `${selectedEvent.id}/${Date.now()}_${safeBase}${ext}`;
      const { error } = await supabase.storage.from(bucket).upload(safeFileName, uploadFileBody, {
        contentType: contentType ?? (uploadFileBody.type || undefined),
      });
      if (error) throw error;
      const { publicUrl } = supabase.storage.from(bucket).getPublicUrl(safeFileName).data;
      return { publicUrl, displayName };
    } catch (err: unknown) {
      toast.error(`파일 업로드 오류: ${storageUploadErrorMessage(err)}`);
      return null;
    } finally {
      setUploading(false);
    }
  };

  const openLessonPlanModal = async () => {
    if (!supabase || !selectedEvent) return;
    setLessonPlanContent(LESSON_PLAN_DEFAULT_TEMPLATE);
    setCurrentSessionLessonPlanId(null);
    setPreviousPlans([]);
    setPreviousPlansExpandedId(null);
    setIsLessonPlanModalOpen(true);
    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.user) return;
    const userId = session.user.id;
    const baseTitle = getBaseTitle(selectedEvent.title);

    const [currentRes, sessionsRes] = await Promise.all([
      supabase.from('lesson_plans').select('id, content').eq('session_id', selectedEvent.id).maybeSingle(),
      supabase.from('sessions').select('id, title, start_at, group_id, lesson_plans(content)').eq('created_by', userId).order('start_at', { ascending: false }).limit(200)
    ]);
    const current = currentRes.data as { id: string; content: string } | null;
    if (current) {
      setLessonPlanContent(
        typeof current.content === 'string' && current.content.trim().length > 0
          ? current.content
          : LESSON_PLAN_DEFAULT_TEMPLATE,
      );
      setCurrentSessionLessonPlanId(current.id);
    }
    const sessionsWithPlans = (sessionsRes.data || []) as Array<{ id: string; title: string; start_at: string; group_id?: string | null; lesson_plans: { content?: string }[] }>;
    const sameClass = sessionsWithPlans.filter(s => s.id !== selectedEvent.id && ((selectedEvent.group_id && s.group_id === selectedEvent.group_id) || getBaseTitle(s.title) === baseTitle));
    const prev: PreviousLessonPlan[] = [];
    sameClass.forEach(s => {
      const raw = s.lesson_plans;
      const lp = Array.isArray(raw) ? raw[0] : raw && typeof raw === 'object' ? raw : null;
      const content = lp && typeof (lp as { content?: string }).content === 'string' ? (lp as { content: string }).content : '';
      if (content.trim()) prev.push({ sessionId: s.id, start_at: s.start_at, content });
    });
    prev.sort((a, b) => new Date(b.start_at).getTime() - new Date(a.start_at).getTime());
    setPreviousPlans(prev);
  };

  const saveLessonPlan = async () => {
    if (!supabase || !selectedEvent) return;
    setLessonPlanSaving(true);
    try {
      const res = await fetch('/api/teacher/lesson-plan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          action: 'save',
          sessionId: selectedEvent.id,
          lessonPlanId: currentSessionLessonPlanId,
          content: lessonPlanContent,
        }),
      });
      const payload = (await res.json().catch(() => ({}))) as { error?: string; lessonPlanId?: string };
      if (!res.ok) throw new Error(payload.error || '저장에 실패했습니다.');
      if (!currentSessionLessonPlanId && payload.lessonPlanId) setCurrentSessionLessonPlanId(payload.lessonPlanId);
      toast.success(currentSessionLessonPlanId ? '수업안이 수정되었습니다.' : '수업안이 저장되었습니다.');
      setIsLessonPlanModalOpen(false);
      getMySchedule();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      toast.error('저장 실패: ' + msg);
    } finally {
      setLessonPlanSaving(false);
    }
  };

  const deleteLessonPlan = async () => {
    if (!supabase || !selectedEvent || !currentSessionLessonPlanId || !confirm('정말 삭제하시겠습니까?')) return;
    setLessonPlanSaving(true);
    try {
      const res = await fetch('/api/teacher/lesson-plan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          action: 'delete',
          sessionId: selectedEvent.id,
          lessonPlanId: currentSessionLessonPlanId,
        }),
      });
      const payload = (await res.json().catch(() => ({}))) as { error?: string };
      if (!res.ok) throw new Error(payload.error || '삭제에 실패했습니다.');
      toast.success('삭제되었습니다.');
      setCurrentSessionLessonPlanId(null);
      setLessonPlanContent(LESSON_PLAN_DEFAULT_TEMPLATE);
      setIsLessonPlanModalOpen(false);
      getMySchedule();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      toast.error('삭제 실패: ' + msg);
    } finally {
      setLessonPlanSaving(false);
    }
  };

  const copyPreviousToContent = (content: string) => {
    setLessonPlanContent(content);
    if (previousPlansExpandedId) setPreviousPlansExpandedId(null);
  };

  if (!currentDate) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[#F8FAFC] pb-20">
        <div className="text-sm font-black uppercase tracking-widest text-slate-300">Syncing...</div>
      </div>
    );
  }

  const { monday, sunday } = getWeekRange(new Date(currentDate));

  return (
    <div className="flex-1 min-h-screen bg-[#F8FAFC] pb-20">
      <div className="max-w-5xl mx-auto p-6 md:p-10 space-y-8 text-left">
        <header className="space-y-6 pb-6 border-b-2 border-slate-200">
          <div className="flex justify-between items-center">
            <div>
              <p className="text-[10px] font-black text-blue-500 uppercase tracking-widest mb-1">SPOKEDU</p>
              <h1 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">MY SCHEDULE</h1>
            </div>
            <button onClick={() => setCurrentDate(new Date())} className="px-4 py-2 bg-white border rounded-xl text-xs font-bold text-slate-500 hover:bg-slate-50 cursor-pointer transition-all active:scale-95">오늘</button>
          </div>
          <div className="flex items-center justify-between bg-white p-2 rounded-2xl shadow-sm border">
            <button
              onClick={() => {
                const next = new Date(currentDate);
                next.setDate(next.getDate() - 7);
                setCurrentDate(next);
              }}
              className="p-3 cursor-pointer"
            >
              <ChevronLeft size={20} className="text-slate-400" />
            </button>
            <span className="text-sm font-black text-slate-700">
              {monday.toLocaleDateString('ko-KR', { month: 'short', day: 'numeric' })} - {sunday.toLocaleDateString('ko-KR', { month: 'short', day: 'numeric' })}
            </span>
            <button
              onClick={() => {
                const next = new Date(currentDate);
                next.setDate(next.getDate() + 7);
                setCurrentDate(next);
              }}
              className="p-3 cursor-pointer"
            >
              <ChevronRight size={20} className="text-slate-400" />
            </button>
          </div>
        </header>

        <div className="grid gap-4">
          {scheduleError ? (
            <div className="py-20 text-center bg-white rounded-[32px] border-2 border-slate-100">
              <p className="text-slate-500 text-sm font-bold mb-3">{scheduleError}</p>
              <button type="button" onClick={getMySchedule} className="text-indigo-600 text-xs font-black hover:underline">
                다시 시도
              </button>
            </div>
          ) : loading ? (
            <div className="py-20 text-center text-slate-400 font-bold animate-pulse">Syncing...</div>
          ) : sessions.length === 0 ? (
            <div className="py-20 text-center bg-white rounded-[32px] border-2 border-dashed border-slate-100 text-slate-300 font-bold text-sm tracking-widest uppercase">No Data</div>
          ) : (
            sessions.map((session) => {
              const startDate = new Date(session.start_at);
              const dayName = startDate.toLocaleDateString('ko-KR', { weekday: 'short' });
              const dateDisplay = `${startDate.getMonth() + 1}.${startDate.getDate()}`;
              const timeDisplay = `${startDate.getHours()}:${String(startDate.getMinutes()).padStart(2, '0')}`;
              
              // 간소화된 상태 판별
              const isCompletedStatus = session.status === 'finished' || session.status === 'verified';
              const feedbackFields =
                isCompletedStatus
                  ? (session.feedback_fields || parseTemplateToFields(session.students_text || ''))
                  : {};
              const isCenterType =
                isCenterSessionType(session.session_type);
              const hasContent = isCenterType
                ? (Array.isArray(session.file_url) ? session.file_url.length > 0 : false)
                : isFieldValid(feedbackFields.main_activity) &&
                  isFieldValid(feedbackFields.strengths) &&
                  isFieldValid(feedbackFields.improvements) &&
                  isFieldValid(feedbackFields.next_goals) &&
                  isFieldValid(feedbackFields.condition_notes);
              
              const isVerified = session.status === 'verified';
              const isPostponed = session.status === 'postponed';
              const isCancelled = session.status === 'cancelled';
              const isActuallyDone = isCompletedStatus && hasContent;
              const isAssistantSession =
                !!scheduleUserId &&
                String(session.created_by || '').trim() !== String(scheduleUserId).trim();

              const statusPill =
                isVerified
                  ? { label: 'Verified', className: 'bg-blue-50 text-blue-500' }
                  : isPostponed
                    ? { label: '연기', className: 'bg-purple-50 text-purple-700' }
                    : isCancelled
                      ? { label: '취소', className: 'bg-rose-50 text-rose-600' }
                      : isActuallyDone
                        ? { label: 'Done', className: 'bg-emerald-50 text-emerald-500' }
                        : { label: 'Wait', className: 'bg-slate-50 text-slate-300' };

              return (
                <div
                  key={session.id}
                  role="button"
                  tabIndex={0}
                  className={`p-4 md:p-6 rounded-[28px] shadow-sm border-2 transition-all cursor-pointer flex items-center justify-between ${isToday(session.start_at) ? 'border-blue-400 bg-blue-50/30' : 'bg-white border-transparent hover:border-slate-200'}`}
                  onClick={() => handleItemClick(session)}
                  onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); handleItemClick(session); } }}
                >
                  <div className="flex items-center gap-4 md:gap-6">
                    <div className={`w-20 h-20 rounded-2xl flex flex-col items-center justify-center shrink-0 ${isToday(session.start_at) ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-900'}`}>
                      <span className={`text-[10px] font-black uppercase mb-0.5 ${isToday(session.start_at) ? 'text-blue-100' : 'text-slate-400'}`}>{dayName} {dateDisplay}</span>
                      <span className="text-lg font-black leading-none">{timeDisplay}</span>
                    </div>
                    <div className="text-left">
                      <div className="flex gap-2 mb-1 flex-wrap">
                        <span className={`text-[9px] font-black px-1.5 py-0.5 rounded uppercase ${isCenterType ? 'bg-indigo-100 text-indigo-600' : 'bg-sky-100 text-sky-600'}`}>{isCenterType ? 'Center' : 'Visit'}</span>
                        {isAssistantSession ? (
                          <span className="text-[9px] font-black px-1.5 py-0.5 rounded uppercase bg-amber-100 text-amber-800">보조</span>
                        ) : null}
                        {isPostponed ? (
                          <span className="text-[9px] font-black px-1.5 py-0.5 rounded uppercase bg-purple-100 text-purple-700">연기됨</span>
                        ) : null}
                      </div>
                      <h3 className="text-base md:text-lg font-black text-slate-800 tracking-tight line-clamp-1">{session.title || 'Untitled'}</h3>
                    </div>
                  </div>
                  <div className={`px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest shrink-0 ${statusPill.className}`}>
                    {statusPill.label}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {isModalOpen && selectedEvent && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[9999] flex items-center justify-center p-4" onClick={() => setIsModalOpen(false)}>
          <div className="bg-white w-full max-w-2xl rounded-[40px] shadow-2xl flex flex-col max-h-[90vh] overflow-hidden animate-in zoom-in duration-200" onClick={e => e.stopPropagation()}>
            <div className="px-4 sm:px-8 py-4 sm:py-6 border-b flex justify-between items-center bg-white sticky top-0 z-10 text-left">
              <div>
                <h2 className="text-base sm:text-xl font-black text-slate-900 tracking-tight uppercase">Session Report</h2>
                <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase">
                  {new Date(selectedEvent.start_at).toLocaleString('ko-KR', { month: 'long', day: 'numeric', weekday: 'short', hour: '2-digit', minute: '2-digit' })}
                </p>
              </div>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={openLessonPlanModal}
                  className="flex items-center gap-1.5 px-3 sm:px-5 py-2.5 sm:py-3.5 rounded-2xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs sm:text-sm font-black transition-all cursor-pointer shadow-lg shadow-indigo-200 active:scale-[0.98]"
                >
                  <FileText size={16} /> <span className="hidden sm:inline">수업안 작성</span><span className="sm:hidden">수업안</span>
                </button>
                <button onClick={() => setIsModalOpen(false)} className="cursor-pointer text-slate-400 hover:text-slate-900 transition-colors p-1"><X size={24} /></button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-6 text-left bg-slate-50/30">
              {/* 센터 수업: 파일 업로드만 */}
              {isCenterSessionType(selectedEvent.session_type) ? (
                <div className="space-y-6">
                  <div className="space-y-4 p-6 bg-blue-50/50 rounded-[32px] border border-blue-100">
                    <div className="flex items-center gap-2 text-blue-600 font-black text-[10px] uppercase tracking-widest">
                      <Paperclip size={14} /> Center Documents
                    </div>
                    <p className="text-[11px] leading-relaxed text-slate-600 font-semibold rounded-xl bg-white/80 border border-blue-100/80 px-3 py-2.5">
                      센터 피드백은 <span className="text-blue-700">파일 1개만</span> 저장됩니다. 새 파일을 올리면 이전 첨부는{' '}
                      <span className="text-blue-700">자동으로 교체</span>되며, 저장소에서 이전 파일도 삭제됩니다.
                      워드·PPT·엑셀·한글(hwpx) 문서에 들어 있는 사진도 업로드 시 자동으로 줄입니다.
                    </p>
                    <div className="grid gap-2">
                      {fileUrls.map((url, i) => (
                        <div key={url} className="flex items-center justify-between bg-white p-3 rounded-xl border border-blue-100 shadow-sm">
                          <span className="text-xs font-bold text-slate-600 truncate max-w-[300px]">
                            {sessionFileDisplayName(url, i, feedbackFields.center_document_names ?? null)}
                          </span>
                          <button
                            type="button"
                            onClick={async () => {
                              if (supabase && url) {
                                const path = sessionFilesObjectPathFromPublicUrl(url);
                                if (path) {
                                  const { error } = await supabase.storage.from(SESSION_FILES_BUCKET).remove([path]);
                                  if (error) devLogger.warn('[my-classes] center file remove', error);
                                }
                              }
                              setFileUrls((prev) => prev.filter((_, idx) => idx !== i));
                              setFeedbackFields((prev) => ({
                                ...prev,
                                center_document_names: Array.isArray(prev.center_document_names)
                                  ? prev.center_document_names.filter((_, idx) => idx !== i)
                                  : [],
                              }));
                            }}
                            className="text-slate-300 hover:text-red-500 cursor-pointer"
                          >
                            <X size={16} />
                          </button>
                        </div>
                      ))}
                      <label className="flex flex-col items-center justify-center gap-1 p-4 bg-white border-2 border-dashed border-blue-200 rounded-xl text-blue-500 hover:bg-blue-50 cursor-pointer transition-all active:scale-[0.99]">
                        <span className="text-xs font-black uppercase tracking-widest">
                          {fileUrls.length > 0 ? '파일 바꾸기' : '+ 파일 올리기'}
                        </span>
                        {fileUrls.length > 0 ? (
                          <span className="text-[10px] font-bold text-slate-400 normal-case tracking-normal">
                            새 파일 선택 시 이전 첨부가 교체됩니다
                          </span>
                        ) : null}
                        <input
                          type="file"
                          className="hidden"
                          onChange={async (e) => {
                            const f = e.target.files?.[0];
                            e.target.value = '';
                            if (!f) return;
                            if (fileUrls.length >= 2) {
                              toast.error('센터 피드백 첨부는 최대 2개까지 가능합니다.');
                              return;
                            }
                            const previousUrls = [...fileUrls];
                            const r = await uploadFile(f, SESSION_FILES_BUCKET);
                            if (!r) return;
                            setFileUrls([...previousUrls, r.publicUrl].slice(0, 2));
                            setFeedbackFields((prev) => ({
                              ...prev,
                              center_document_names: [...(Array.isArray(prev.center_document_names) ? prev.center_document_names : []), r.displayName].slice(0, 2),
                            }));
                          }}
                          disabled={uploading}
                        />
                      </label>
                    </div>
                  </div>
                  
                  {/* 센터 수업 메모 (선택) */}
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1 mb-2">
                      메모 (선택사항)
                    </label>
                    <textarea 
                      className="w-full h-32 bg-white rounded-2xl p-4 text-sm leading-relaxed text-slate-700 outline-none focus:ring-2 focus:ring-blue-100 shadow-sm border border-slate-100 resize-none transition-all"
                      value={feedbackFields.condition_notes || ''}
                      onChange={(e) => setFeedbackFields({...feedbackFields, condition_notes: e.target.value})}
                      placeholder="특이사항이나 간단한 메모를 남겨주세요"
                    />
                  </div>
                </div>
              ) : (
                /* 개인 수업: 구조화된 필드 입력 */
                <>
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1 mb-2">
                    ✅ 오늘 수업의 주요 활동 *
                  </label>
                  <textarea 
                    className="w-full h-24 bg-white rounded-2xl p-4 text-sm leading-relaxed text-slate-700 outline-none focus:ring-2 focus:ring-blue-100 shadow-sm border border-slate-100 resize-none transition-all"
                    value={feedbackFields.main_activity || ''}
                    onChange={(e) => setFeedbackFields({...feedbackFields, main_activity: e.target.value})}
                    placeholder="예: 축구 기본기 드리블 연습, 미니 게임 진행"
                  />
                </div>

                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1 mb-2">
                    ✅ 강점 및 긍정적인 부분 *
                  </label>
                  <textarea 
                    className="w-full h-24 bg-white rounded-2xl p-4 text-sm leading-relaxed text-slate-700 outline-none focus:ring-2 focus:ring-blue-100 shadow-sm border border-slate-100 resize-none transition-all"
                    value={feedbackFields.strengths || ''}
                    onChange={(e) => setFeedbackFields({...feedbackFields, strengths: e.target.value})}
                    placeholder="예: 드리블 속도가 빨라졌고, 팀워크가 좋아졌습니다"
                  />
                </div>

                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1 mb-2">
                    ✅ 개선이 필요한 부분 및 피드백 *
                  </label>
                  <textarea 
                    className="w-full h-24 bg-white rounded-2xl p-4 text-sm leading-relaxed text-slate-700 outline-none focus:ring-2 focus:ring-blue-100 shadow-sm border border-slate-100 resize-none transition-all"
                    value={feedbackFields.improvements || ''}
                    onChange={(e) => setFeedbackFields({...feedbackFields, improvements: e.target.value})}
                    placeholder="예: 슈팅 정확도 연습이 더 필요합니다"
                  />
                </div>

                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1 mb-2">
                    ✅ 다음 수업 목표 및 계획 *
                  </label>
                  <textarea 
                    className="w-full h-24 bg-white rounded-2xl p-4 text-sm leading-relaxed text-slate-700 outline-none focus:ring-2 focus:ring-blue-100 shadow-sm border border-slate-100 resize-none transition-all"
                    value={feedbackFields.next_goals || ''}
                    onChange={(e) => setFeedbackFields({...feedbackFields, next_goals: e.target.value})}
                    placeholder="예: 패스 연습과 전술 이해도 향상"
                  />
                </div>

                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1 mb-2">
                    ✅ 특이사항 및 시작/종료 시간 *
                  </label>
                  <textarea 
                    className="w-full h-24 bg-white rounded-2xl p-4 text-sm leading-relaxed text-slate-700 outline-none focus:ring-2 focus:ring-blue-100 shadow-sm border border-slate-100 resize-none transition-all"
                    value={feedbackFields.condition_notes || ''}
                    onChange={(e) => setFeedbackFields({...feedbackFields, condition_notes: e.target.value})}
                    placeholder="예: 14:00 시작, 15:30 종료"
                  />
                </div>
              </div>

                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1">
                    Photos ({photoUrls.length})
                  </label>
                  <div className="grid grid-cols-3 gap-3">
                    {photoUrls.map((url, i) => (
                      <div key={i} className="relative aspect-square">
                        <img src={url} className="w-full h-full rounded-2xl object-cover border-2 border-white shadow-md" alt="" referrerPolicy="no-referrer" />
                        <button onClick={() => setPhotoUrls(photoUrls.filter((_, idx) => idx !== i))} className="absolute -top-2 -right-2 bg-red-500 text-white w-6 h-6 rounded-full flex items-center justify-center shadow-lg cursor-pointer"><X size={12} /></button>
                      </div>
                    ))}
                    <label className="aspect-square rounded-2xl border-2 border-dashed border-slate-200 flex flex-col items-center justify-center bg-white text-slate-300 hover:bg-slate-50 hover:border-blue-400 cursor-pointer transition-all active:scale-95">
                      <Camera size={24} />
                      <input type="file" className="hidden" accept="image/*" onChange={async (e) => {
                        const f = e.target.files?.[0];
                        e.target.value = '';
                        if (!f) return;
                        const r = await uploadFile(f, 'session-photos');
                        if (r) setPhotoUrls((prev) => [...prev, r.publicUrl]);
                      }} disabled={uploading} />
                    </label>
                  </div>
                </div>
              </>
              )}
            </div>

            <div className="p-4 sm:p-8 bg-white border-t flex gap-4">
              {selectedEvent.status === 'finished' && (
                <button onClick={handleResetStatus} disabled={uploading} className="flex-1 bg-slate-100 text-slate-400 py-5 rounded-[22px] font-black text-sm cursor-pointer hover:bg-red-50 transition-all uppercase">Reset</button>
              )}
              <button onClick={handleCompleteSession} disabled={uploading} className={`flex-[2] py-5 rounded-[22px] font-black text-sm shadow-xl transition-all cursor-pointer active:scale-95 uppercase ${uploading ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-blue-600'}`}>
                {uploading ? 'Processing...' : 'Complete & Save'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 수업안 작성/수정 모달 */}
      {isLessonPlanModalOpen && selectedEvent && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[10000] flex items-center justify-center p-4" onClick={() => setIsLessonPlanModalOpen(false)}>
          <div className="bg-white w-full max-w-2xl rounded-[40px] shadow-2xl flex flex-col max-h-[90vh]" onClick={e => e.stopPropagation()}>
            <div className="px-4 sm:px-8 py-4 sm:py-6 border-b flex justify-between items-center bg-white text-left">
              <div>
                <h2 className="text-xl font-black text-slate-900 tracking-tight">수업안</h2>
                <p className="text-[10px] font-bold text-slate-400 mt-1">
                  {selectedEvent.title} · {new Date(selectedEvent.start_at).toLocaleString('ko-KR', { dateStyle: 'short', timeStyle: 'short' })}
                </p>
              </div>
              <button type="button" onClick={() => setIsLessonPlanModalOpen(false)} className="cursor-pointer text-slate-400 hover:text-slate-900 transition-colors"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 sm:p-8 space-y-6 bg-slate-50/30 text-left">
              {/* 이전 수업안: 항상 표시 (없을 때 안내 문구) */}
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1 mb-2">이전 수업안 (같은 수업 다른 날짜 · 복사해서 사용)</label>
                {previousPlans.length > 0 ? (
                  <div className="space-y-2">
                    {previousPlans.map((p) => {
                      const isExp = previousPlansExpandedId === p.sessionId;
                      return (
                        <div key={p.sessionId} className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
                          <button
                            type="button"
                            onClick={() => setPreviousPlansExpandedId(isExp ? null : p.sessionId)}
                            className="w-full px-4 py-3 flex justify-between items-center text-left hover:bg-slate-50 cursor-pointer"
                          >
                            <span className="text-sm font-bold text-slate-700">
                              {new Date(p.start_at).toLocaleString('ko-KR', { dateStyle: 'short', timeStyle: 'short' })}
                            </span>
                            {isExp ? <ChevronUp size={18} className="text-slate-400" /> : <ChevronDown size={18} className="text-slate-400" />}
                          </button>
                          {isExp && (
                            <div className="px-4 pb-4 pt-0 border-t border-slate-100">
                              <pre className="text-xs text-slate-600 whitespace-pre-wrap font-sans max-h-40 overflow-y-auto p-3 bg-slate-50 rounded-xl mb-3">{p.content}</pre>
                              <button
                                type="button"
                                onClick={() => copyPreviousToContent(p.content)}
                                className="flex items-center gap-1.5 px-3 py-2 rounded-lg bg-indigo-100 text-indigo-700 text-xs font-black cursor-pointer hover:bg-indigo-200 transition-all"
                              >
                                <Copy size={14} /> 내용 가져오기
                              </button>
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <p className="text-sm text-slate-400 py-4 px-4 bg-white rounded-2xl border border-slate-100">
                    같은 수업의 이전 회차 수업안이 없습니다. 다른 날짜에 작성한 같은 수업 수업안이 여기 목록으로 표시됩니다.
                  </p>
                )}
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block ml-1 mb-2">이번 수업안 내용</label>
                <textarea
                  className="w-full min-h-[280px] bg-white rounded-2xl p-6 text-sm leading-relaxed text-slate-700 outline-none focus:ring-2 focus:ring-blue-100 shadow-sm border border-slate-100 resize-none transition-all"
                  value={lessonPlanContent}
                  onChange={(e) => setLessonPlanContent(e.target.value)}
                  placeholder="수업안을 작성하세요..."
                />
              </div>
            </div>
            <div className="p-4 sm:p-8 bg-white border-t flex gap-4">
              {currentSessionLessonPlanId && (
                <button type="button" onClick={deleteLessonPlan} disabled={lessonPlanSaving} className="flex-1 bg-rose-50 text-rose-500 py-5 rounded-[22px] font-black text-sm cursor-pointer hover:bg-rose-100 transition-all uppercase disabled:opacity-50">삭제</button>
              )}
              <button type="button" onClick={saveLessonPlan} disabled={lessonPlanSaving} className={`flex-[2] py-5 rounded-[22px] font-black text-sm shadow-xl transition-all cursor-pointer active:scale-95 uppercase ${lessonPlanSaving ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-blue-600'}`}>
                {lessonPlanSaving ? '저장 중...' : currentSessionLessonPlanId ? '수정' : '저장'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default function MyClassesPage() {
  return (
    <Suspense fallback={<div className="p-20 text-center font-bold text-slate-300">Syncing...</div>}>
      <MyClassesContent />
    </Suspense>
  );
}

