import nextEnv from '@next/env';
import { spawnSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadMasterQaEnv } from './lib/spokedu-master-qa-env.mjs';

const { loadEnvConfig } = nextEnv;
loadMasterQaEnv();

const BASE = (process.argv.find((arg) => /^https?:\/\//.test(arg)) || 'http://localhost:3000').replace(/\/$/, '');
const OUTPUT_DIR = process.argv.includes('--stdout-only')
  ? null
  : join(process.cwd(), 'commercial-verification');

const VITEST_BIN = join(process.cwd(), 'node_modules', 'vitest', 'vitest.mjs');
const ENTRY_COPY_CONTRACT_TEST = 'app/spokedu-master/masterEntryCopy.contract.test.ts';
const API_ROUTE_IMPORTS_CONTRACT_TEST = 'app/api/spokedu-master/apiRouteImports.contract.test.ts';

const CHECKS = [
  { id: 'api_route_imports', kind: 'vitest', target: API_ROUTE_IMPORTS_CONTRACT_TEST },
  { id: 'production_build', kind: 'npm', script: 'build' },
  { id: 'entry_copy_contract', kind: 'vitest', target: ENTRY_COPY_CONTRACT_TEST },
  { id: 'entitlement_matrix_contract', kind: 'vitest', target: 'app/spokedu-master/entitlementMatrix.contract.test.ts' },
  { id: 'day_loop_contract', kind: 'vitest', target: 'app/spokedu-master/dayLoop.contract.test.ts' },
  { id: 'craft_p3_contract', kind: 'vitest', target: 'app/spokedu-master/craftP3.contract.test.ts' },
  { id: 'owner_isolation_contract', kind: 'vitest', target: 'app/spokedu-master/ownerIsolation.contract.test.ts' },
  { id: 'billing_readiness_p5_contract', kind: 'vitest', target: 'app/spokedu-master/billingReadinessP5.contract.test.ts' },
  { id: 'live_gate_p6_contract', kind: 'vitest', target: 'app/spokedu-master/liveGateP6.contract.test.ts' },
  { id: 'restore_readiness_p7_contract', kind: 'vitest', target: 'app/spokedu-master/restoreReadinessP7.contract.test.ts' },
  { id: 'staging_payment_preflight', kind: 'node', script: 'scripts/spokedu-master-staging-payment-e2e.mjs', args: [] },
  { id: 'payment_no_toss', kind: 'node', script: 'scripts/spokedu-master-staging-payment-e2e.mjs', args: ['--mock-activation'] },
  { id: 'profile_persist', kind: 'node', script: 'scripts/spokedu-master-profile-persist-e2e.mjs', args: [] },
  { id: 'ops_readiness', kind: 'node', script: 'scripts/spokedu-master-ops-readiness.mjs', args: [] },
  { id: 'library_content', kind: 'node', script: 'scripts/spokedu-master-library-content-readiness.mjs', args: [] },
  { id: 'production_prep', kind: 'node', script: 'scripts/spokedu-master-production-prep.mjs', args: [] },
];

function extractLastJson(text) {
  const lines = String(text ?? '').split(/\r?\n/);
  for (let index = lines.length - 1; index >= 0; index -= 1) {
    const line = lines[index].trim();
    if (!line.startsWith('{')) continue;
    try {
      return JSON.parse(line);
    } catch {
      // keep scanning upward for multiline JSON blocks
    }
  }

  const match = String(text ?? '').match(/\{[\s\S]*\}\s*$/);
  if (!match) return null;
  try {
    return JSON.parse(match[0]);
  } catch {
    return null;
  }
}

function runCheck(check) {
  const startedAt = Date.now();

  if (check.kind === 'vitest') {
    const result = spawnSync(process.execPath, [VITEST_BIN, 'run', check.target], {
      cwd: process.cwd(),
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    const exitCode = result.status ?? 1;
    return {
      id: check.id,
      script: `vitest run ${check.target}`,
      ok: exitCode === 0,
      exitCode,
      durationMs: Date.now() - startedAt,
      detail: { phase: 'contract-test', target: check.target },
      stderrTail: result.stderr?.trim() ? result.stderr.trim().slice(-400) : undefined,
    };
  }

  if (check.kind === 'npm') {
    const npmCmd = process.platform === 'win32' ? 'npm.cmd' : 'npm';
    const result = spawnSync(npmCmd, ['run', check.script], {
      cwd: process.cwd(),
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      env: {
        ...process.env,
        NEXT_PUBLIC_SUPABASE_URL: process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://example.supabase.co',
        NEXT_PUBLIC_SUPABASE_ANON_KEY: process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || 'ci-anon-key',
        SUPABASE_SERVICE_ROLE_KEY: process.env.SUPABASE_SERVICE_ROLE_KEY || 'ci-service-role-key',
      },
    });
    const exitCode = result.status ?? 1;
    return {
      id: check.id,
      script: `npm run ${check.script}`,
      ok: exitCode === 0,
      exitCode,
      durationMs: Date.now() - startedAt,
      detail: { phase: 'production-build' },
      stderrTail: result.stderr?.trim() ? result.stderr.trim().slice(-400) : undefined,
    };
  }

  const result = spawnSync(
    process.execPath,
    [check.script, BASE, ...check.args],
    {
      cwd: process.cwd(),
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    },
  );

  const stdout = result.stdout ?? '';
  const stderr = result.stderr ?? '';
  const exitCode = result.status ?? 1;

  return {
    id: check.id,
    script: check.script,
    ok: exitCode === 0,
    exitCode,
    durationMs: Date.now() - startedAt,
    detail: extractLastJson(stdout) ?? undefined,
    stderrTail: stderr.trim() ? stderr.trim().slice(-400) : undefined,
  };
}

function buildScore(results) {
  const passed = results.filter((item) => item.ok).length;
  const base = 76;
  const weights = {
    api_route_imports: 0,
    production_build: 2,
    entry_copy_contract: 1,
    entitlement_matrix_contract: 1,
    day_loop_contract: 1,
    craft_p3_contract: 1,
    owner_isolation_contract: 1,
    billing_readiness_p5_contract: 1,
    staging_payment_preflight: 1,
    payment_no_toss: 1,
    profile_persist: 1,
    ops_readiness: 1,
    library_content: 1,
    production_prep: 0,
  };
  const earned = results.reduce((sum, item) => sum + (item.ok ? (weights[item.id] ?? 0) : 0), 0);
  const maxEarned = Object.values(weights).reduce((sum, value) => sum + value, 0);
  const score = base + earned;
  return {
    strictCommercialScore: score,
    maxWithoutTossSandbox: base + maxEarned,
    passed,
    total: results.length,
    nextMilestone: 'Toss sandbox real payment + webhook/subscription verification (+2~3). strictCommercialScore ≠ D 8+.',
  };
}

function main() {
  console.log(`[commercial-verification] base=${BASE}`);
  const results = CHECKS.map((check) => {
    console.log(`[commercial-verification] running ${check.id}...`);
    const outcome = runCheck(check);
    console.log(`[commercial-verification] ${outcome.ok ? 'OK' : 'FAIL'} ${check.id} (${outcome.durationMs}ms)`);
    return outcome;
  });

  const failed = results.filter((item) => !item.ok);
  const score = buildScore(results);
  const report = {
    ok: failed.length === 0,
    generatedAt: new Date().toISOString(),
    baseUrl: BASE,
    phase: 'no-payment-commercial-gate',
    checks: results,
    score,
    blockers: failed.map((item) => item.id),
    warnings: results
      .flatMap((item) => {
        const direct = item.detail?.warnings ?? [];
        if (Array.isArray(direct) && direct.every((entry) => typeof entry === 'string')) return direct;
        if (Array.isArray(direct)) {
          return direct.map((entry) => (
            typeof entry === 'string'
              ? entry
              : `${entry.name}${entry.detail ? `: ${entry.detail}` : ''}`
          ));
        }
        return [];
      })
      .filter(Boolean),
    next: failed.length === 0
      ? 'Payment deferred: complete production env (CRON_SECRET, monitoring webhook, restore DB URL), release checklist manual items, then Toss sandbox when ready'
      : `Fix failed checks first: ${failed.map((item) => item.id).join(', ')}`,
  };

  const serialized = `${JSON.stringify(report, null, 2)}\n`;
  if (OUTPUT_DIR) {
    mkdirSync(OUTPUT_DIR, { recursive: true });
    const outputPath = join(OUTPUT_DIR, 'commercial-verification-report.json');
    writeFileSync(outputPath, serialized, 'utf8');
    console.log(`[commercial-verification] wrote ${outputPath}`);
  }

  process.stdout.write(serialized);
  process.exit(report.ok ? 0 : 1);
}

main();

/**
 * MASTER 홈 비주얼(16:9 전용 썸네일) 점검 — 정적 data.ts + public 파일 존재
 * Usage: node scripts/spokedu-master-home-visual-audit.mjs
 */
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dataPath = join(root, 'app/spokedu-master/lib/data.ts');
const source = readFileSync(dataPath, 'utf8');

const DEDICATED_PREFIX = '/images/spokedu-master/programs/';
const GENERIC_PATTERNS = [
  /\/images\/spokedu\/records\//,
  /\/images\/spokedu\/cases\/hero/,
  /\/images\/spokedu\/curriculum-instructor/,
  /img\.youtube\.com/,
];

function extractProgramBlocks(text) {
  return text.split(/\n  \{\n    id: '/).slice(1);
}

function parseImageUrls(block) {
  const urls = [];
  for (const match of block.matchAll(/(?:heroImageUrl|thumbnailUrl):\s*['"]([^'"]+)['"]/g)) {
    urls.push(match[1]);
  }
  return [...new Set(urls)];
}

function isDedicated(url) {
  return url.startsWith(DEDICATED_PREFIX);
}

function isGeneric(url) {
  return GENERIC_PATTERNS.some((pattern) => pattern.test(url));
}

function publicPath(url) {
  if (!url.startsWith('/images/')) return null;
  const segments = url.replace(/^\//, '').split('/');
  return join(root, 'public', ...segments);
}

function dedicatedHeroExists(url) {
  const file = publicPath(url);
  if (!file) return false;
  if (existsSync(file)) return true;
  if (url.endsWith('.jpeg')) {
    return existsSync(file.replace(/\.jpeg$/i, '.svg'));
  }
  return false;
}

const blocks = extractProgramBlocks(source);
const rows = blocks.map((block) => {
  const id = block.split("'")[0];
  const urls = parseImageUrls(block);
  const dedicated = urls.filter(isDedicated);
  const generic = urls.filter((url) => !isDedicated(url));
  const missing = urls
    .filter((url) => url.startsWith('/images/'))
    .filter((url) => !dedicatedHeroExists(url));
  const hasRules = /rules:\s*\[/.test(block) && !/rules:\s*\[\s*\]/.test(block);
  const isHot = /isHot:\s*true/.test(block);
  return { id, urls, dedicated, generic, missing, hasRules, isHot };
});

const hot = rows.filter((row) => row.isHot);
const dedicatedHot = hot.filter((row) => row.dedicated.length > 0);
const missingFiles = rows.flatMap((row) => row.missing.map((url) => ({ id: row.id, url })));

console.log('=== SPOKEDU MASTER home visual audit ===');
console.log(`HOT programs: ${hot.length}`);
console.log(`HOT with dedicated 16:9 path: ${dedicatedHot.length} / ${hot.length}`);
console.log(`Missing image files: ${missingFiles.length}`);

for (const row of rows.filter((r) => r.isHot)) {
  const visual = row.dedicated.length > 0 ? 'dedicated' : row.generic.length > 0 ? 'generic-fallback' : 'no-visual';
  const miss = row.missing.length > 0 ? ` MISSING:${row.missing.join(',')}` : '';
  console.log(`  HOT ${row.id} — ${visual}${miss}`);
}

if (missingFiles.length > 0) {
  console.error('\nMissing files (upload to public/ or fix data.ts):');
  for (const item of missingFiles) {
    console.error(`  ${item.id}: ${item.url}`);
  }
}

const targetDedicatedHot = 3;
if (dedicatedHot.length < targetDedicatedHot) {
  console.warn(`\nWARN: dedicated HOT visuals ${dedicatedHot.length} < ${targetDedicatedHot} (content task)`);
}

if (missingFiles.length > 0) {
  console.warn('\nContent backlog: upload 16:9 files under public/images/spokedu-master/programs/{slug}/hero.jpeg');
}

console.log('\nVisual audit finished (exit 0 — missing files are warnings until assets land).');

import nextEnv from '@next/env';

const { loadEnvConfig } = nextEnv;
loadEnvConfig(process.cwd());

const BASE = (process.argv.find((arg) => /^https?:\/\//.test(arg)) || 'http://localhost:3000').replace(/\/$/, '');
const MANUAL_ONLY = process.argv.includes('--manual-only');
const MOCK_ACTIVATION = process.argv.includes('--mock-activation');
const SKIP_SERVER = process.argv.includes('--skip-server-check');

const QA_ID = process.env.SPOKEDU_MASTER_QA_ID || process.env.SPM_QA_ID || '';
const QA_PASSWORD = process.env.SPOKEDU_MASTER_QA_PASSWORD || process.env.SPM_QA_PASSWORD || '';
const PAYMENT_QA_ID =
  process.env.SPOKEDU_MASTER_QA_SECONDARY_ID ||
  process.env.SPM_QA_EXPIRED_EMAIL ||
  'spm.qa.expired@spokedu.test';
const PAYMENT_QA_PASSWORD =
  process.env.SPOKEDU_MASTER_QA_SECONDARY_PASSWORD ||
  process.env.SPM_QA_EXPIRED_PASSWORD ||
  QA_PASSWORD;
const PLAN = process.env.SPOKEDU_MASTER_PAYMENT_E2E_PLAN === 'premium' ? 'premium' : 'lite';
const AUTH_KEY = process.env.SPOKEDU_MASTER_PAYMENT_E2E_AUTH_KEY || '';
const CUSTOMER_KEY = process.env.SPOKEDU_MASTER_PAYMENT_E2E_CUSTOMER_KEY || '';

const TOSS_CLIENT = process.env.NEXT_PUBLIC_TOSS_CLIENT_KEY || '';
const TOSS_SECRET = process.env.TOSS_SECRET_KEY || '';

function log(step, detail = '') {
  console.log(detail ? `[payment-e2e] ${step} — ${detail}` : `[payment-e2e] ${step}`);
}

function fail(message) {
  console.error(`[payment-e2e] FAIL: ${message}`);
  process.exit(1);
}

function assert(condition, message) {
  if (!condition) fail(message);
}

function isTestTossKey(value) {
  return /^test_/i.test(value);
}

async function loadPlaywright() {
  try {
    const mod = await import('playwright');
    return mod.chromium;
  } catch {
    fail('playwright is not installed');
  }
}

async function assertServerReachable() {
  const response = await fetch(`${BASE}/login`, { method: 'HEAD', redirect: 'manual' }).catch(() => null);
  assert(response && response.status < 500, `dev server not reachable at ${BASE}`);
}

async function login(context, { id = PAYMENT_QA_ID, password = PAYMENT_QA_PASSWORD, next = `/spokedu-master/payment?plan=${PLAN}` } = {}) {
  const page = await context.newPage();
  await page.goto(`${BASE}/login?next=${encodeURIComponent(next)}`, {
    waitUntil: 'domcontentloaded',
  });
  const passwordInput = page.locator('input[type="password"]').first();
  if ((await passwordInput.count()) === 0) {
    await page.locator('[role="tab"]').nth(1).waitFor({ state: 'visible', timeout: 10_000 });
    await page.locator('[role="tab"]').nth(1).click();
  }
  await passwordInput.waitFor({ state: 'visible', timeout: 10_000 });
  await page.locator('input[type="text"], input[type="email"]').first().fill(id);
  await passwordInput.fill(password);
  await page.locator('button[type="submit"]').click();
  await page.waitForURL(/\/spokedu-master\//, { timeout: 90_000, waitUntil: 'domcontentloaded' });
  await page.close();
}

async function fetchJson(context, path) {
  const response = await context.request.get(`${BASE}${path}`, { headers: { accept: 'application/json' } });
  const body = await response.json().catch(() => null);
  return { status: response.status(), body };
}

async function postJson(context, path, payload) {
  const response = await context.request.post(`${BASE}${path}`, {
    headers: { 'content-type': 'application/json', accept: 'application/json' },
    data: payload,
  });
  const body = await response.json().catch(() => null);
  return { status: response.status(), body };
}

async function verifyAccessAfterPayment(context, plan) {
  for (let attempt = 1; attempt <= 8; attempt += 1) {
    const { status, body } = await fetchJson(context, '/api/spokedu-master/access');
    if (status === 200 && body?.allowed === true && body?.plan === plan) {
      assert(body.canUseLibrary === true, 'canUseLibrary is false after payment');
      assert(body.onboardingDone === true, 'onboardingDone is false after paid activation');
      log('access verified', `plan=${plan} attempt=${attempt}`);
      return body;
    }
    await new Promise((resolve) => setTimeout(resolve, 800));
  }
  fail('access did not activate after billing/issue');
}

function activeAccessSnapshot(plan) {
  const periodEnd = new Date(Date.now() + 10_000 * 60_000).toISOString();
  return {
    authenticated: true,
    allowed: true,
    onboardingDone: true,
    plan,
    subscriptionStatus: 'active',
    currentPeriodEnd: periodEnd,
    cancelAtPeriodEnd: false,
    isAdmin: false,
    isCenterOrTeam: false,
    canUseLibrary: true,
    canUseClassTools: true,
    canUseAttendance: true,
    canUseRecords: plan === 'premium',
    canUseSpomove: plan === 'premium',
  };
}

async function runMockActivation(context, plan) {
  const page = await context.newPage();
  let billingCalls = 0;
  let accessCalls = 0;

  await page.route('**/api/spokedu-master/payment/billing/issue', async (route) => {
    billingCalls += 1;
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({
        ok: true,
        alreadyConfirmed: false,
        plan,
        periodEnd: new Date(Date.now() + 10_000 * 60_000).toISOString(),
      }),
    });
  });
  await page.route('**/api/spokedu-master/access', async (route) => {
    accessCalls += 1;
    if (accessCalls === 1) {
      await route.fulfill({
        status: 403,
        contentType: 'application/json',
        body: JSON.stringify({ ok: false, allowed: false, code: 'subscription_required' }),
      });
      return;
    }
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify(activeAccessSnapshot(plan)),
      headers: { 'Cache-Control': 'private, no-store, max-age=0', Vary: 'Cookie, Authorization' },
    });
  });
  await page.route('**/api/spokedu-master/subscription', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({
        plan,
        status: 'active',
        isAdmin: false,
        periodEnd: new Date(Date.now() + 10_000 * 60_000).toISOString(),
        trialEndsAt: null,
      }),
    });
  });
  await page.route('**/spokedu-master/library', async (route) => {
    if (route.request().resourceType() !== 'document') {
      await route.fallback();
      return;
    }
    await route.fulfill({
      status: 200,
      contentType: 'text/html; charset=utf-8',
      body: '<!doctype html><html><body><main>Mock library reached after payment activation.</main></body></html>',
    });
  });

  await page.goto(
    `${BASE}/spokedu-master/payment/success?plan=${plan}&authKey=auth_mock_no_toss&customerKey=spm_mock_no_toss`,
    { waitUntil: 'domcontentloaded' },
  );
  await page.getByText('결제가 완료되었습니다').waitFor({ state: 'visible', timeout: 15_000 });
  assert(billingCalls === 1, `billing/issue mock was called ${billingCalls} times`);
  assert(accessCalls >= 2, `access polling mock was called ${accessCalls} times`);

  const libraryLink = page.locator('a[href="/spokedu-master/library"]').first();
  await libraryLink.waitFor({ state: 'visible', timeout: 10_000 });
  const href = await libraryLink.getAttribute('href');
  assert(href === '/spokedu-master/library', 'success CTA does not point to library');
  log('mock-activation', `success UI + library CTA ok (plan=${plan}, no Toss)`);
  await page.close();
}

function printManualTossSteps(plan) {
  console.log('\n[payment-e2e] MANUAL TOSS SANDBOX STEPS');
  console.log(`1. Open ${BASE}/spokedu-master/payment?plan=${plan}`);
  console.log('2. Log in with the disposable QA account if needed.');
  console.log(`3. Select ${plan === 'lite' ? 'Lite' : 'Premium'} and complete Toss test billing auth.`);
  console.log('4. On success redirect, confirm dashboard CTA and library entry.');
  console.log('5. Optional API replay (same browser session cookies required):');
  console.log('   set SPOKEDU_MASTER_PAYMENT_E2E_PLAN=lite|premium');
  console.log('   set SPOKEDU_MASTER_PAYMENT_E2E_AUTH_KEY=<authKey from success URL>');
  console.log('   set SPOKEDU_MASTER_PAYMENT_E2E_CUSTOMER_KEY=<customerKey from success URL>');
  console.log(`   node scripts/spokedu-master-staging-payment-e2e.mjs ${BASE} --complete-billing\n`);
}

async function main() {
  log('base', BASE);

  if (!SKIP_SERVER) {
    await assertServerReachable();
    log('server', 'reachable');
  }

  if (MOCK_ACTIVATION) {
    const chromium = await loadPlaywright();
    const browser = await chromium.launch({ headless: true });
    const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
    try {
      await runMockActivation(context, PLAN);
      console.log(JSON.stringify({
        ok: true,
        phase: 'mock-activation',
        plan: PLAN,
        tossRequired: false,
        verified: ['billing-issue-mock', 'access-retry-mock', 'success-ui', 'library-cta'],
      }));
      return;
    } finally {
      await context.close().catch(() => undefined);
      await browser.close().catch(() => undefined);
    }
  }

  assert(QA_PASSWORD, 'SPOKEDU_MASTER_QA_PASSWORD (or SPM_QA_PASSWORD) is required');
  assert(PAYMENT_QA_ID && PAYMENT_QA_PASSWORD, 'payment QA credentials are required (secondary/expired account)');
  assert(isTestTossKey(TOSS_CLIENT), 'NEXT_PUBLIC_TOSS_CLIENT_KEY must be a Toss test key');
  assert(isTestTossKey(TOSS_SECRET), 'TOSS_SECRET_KEY must be a Toss test key');

  if (MANUAL_ONLY) {
    printManualTossSteps(PLAN);
    return;
  }

  const chromium = await loadPlaywright();
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 390, height: 844 } });

  try {
    await login(context);
    log('login', `ok (${PAYMENT_QA_ID})`);

    const profile = await fetchJson(context, '/api/spokedu-master/profile');
    assert(profile.status === 200, `profile API returned ${profile.status}`);
    log('profile', `onboardingDone=${profile.body?.onboardingDone === true}`);

    const subscriptionBefore = await fetchJson(context, '/api/spokedu-master/subscription');
    assert(subscriptionBefore.status === 200, `subscription API returned ${subscriptionBefore.status}`);
    log('subscription-before', `plan=${subscriptionBefore.body?.plan ?? 'unknown'} status=${subscriptionBefore.body?.status ?? 'unknown'}`);

    const accessBefore = await fetchJson(context, '/api/spokedu-master/access');
    log('access-before', `status=${accessBefore.status} allowed=${accessBefore.body?.allowed === true}`);

    const paymentPage = await context.newPage();
    await paymentPage.goto(`${BASE}/spokedu-master/payment?plan=${PLAN}`, { waitUntil: 'domcontentloaded' });
    await paymentPage.waitForLoadState('networkidle').catch(() => undefined);
    const paymentText = await paymentPage.locator('body').innerText();
    assert(/이용권|라이트|프리미엄/.test(paymentText), 'payment page did not render plan copy');
    assert(await paymentPage.locator(`button[data-plan-id="${PLAN}"]`).count() >= 1, `${PLAN} plan button missing`);
    await paymentPage.waitForFunction(() => typeof window.TossPayments === 'function', undefined, { timeout: 15_000 }).catch(() => {
      fail('TossPayments SDK did not load on payment page');
    });
    log('payment-page', `Toss SDK loaded, plan=${PLAN}`);
    await paymentPage.close();

    if (process.argv.includes('--complete-billing')) {
      assert(AUTH_KEY && CUSTOMER_KEY, 'SPOKEDU_MASTER_PAYMENT_E2E_AUTH_KEY and CUSTOMER_KEY are required for --complete-billing');
      const issue = await postJson(context, '/api/spokedu-master/payment/billing/issue', {
        planId: PLAN,
        authKey: AUTH_KEY,
        customerKey: CUSTOMER_KEY,
      });
      assert(issue.status === 200 && issue.body?.ok === true, `billing/issue failed: status=${issue.status}`);
      log('billing-issue', `plan=${issue.body?.plan ?? PLAN}`);

      const access = await verifyAccessAfterPayment(context, PLAN);
      const libraryPage = await context.newPage();
      await libraryPage.goto(`${BASE}/spokedu-master/library`, { waitUntil: 'domcontentloaded' });
      await libraryPage.waitForLoadState('networkidle').catch(() => undefined);
      const libraryText = await libraryPage.locator('body').innerText();
      assert(!/이용권이 필요/.test(libraryText), 'library still gated after payment');
      log('library', 'accessible after payment');
      await libraryPage.close();

      const profileAfter = await fetchJson(context, '/api/spokedu-master/profile');
      assert(profileAfter.body?.onboardingDone === true, 'profile onboardingDone not persisted after payment');
      log('profile-after', 'onboardingDone=true');

      console.log(JSON.stringify({ ok: true, phase: 'full-billing', plan: PLAN, canUseLibrary: access.canUseLibrary }));
      return;
    }

    printManualTossSteps(PLAN);
    console.log(JSON.stringify({
      ok: true,
      phase: 'preflight',
      plan: PLAN,
      profileOk: profile.status === 200,
      tossSdkOk: true,
      accessBefore: accessBefore.body?.allowed === true,
      next: 'complete Toss sandbox manually, then rerun with --complete-billing and authKey/customerKey env vars',
    }));
  } finally {
    await context.close().catch(() => undefined);
    await browser.close().catch(() => undefined);
  }
}

main().catch((error) => {
  fail(error instanceof Error ? error.message : String(error));
});

/**
 * Spokedu deep QA — contact links, form state, CTA heights
 */
import { chromium } from 'playwright';
import { writeFileSync, mkdirSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const BASE = process.argv[2] || 'http://localhost:3000';
const OUT_DIR = join(__dirname, '../.qa-spokedu');
mkdirSync(OUT_DIR, { recursive: true });

const PAGES = [
  '/spokedu',
  '/spokedu/about',
  '/spokedu/private',
  '/spokedu/dispatch',
  '/spokedu/curriculum',
  '/spokedu/programs/spomove',
  '/spokedu/programs/paps',
  '/spokedu/programs/oneday-event',
  '/spokedu/programs/camp',
  '/spokedu/records',
  '/spokedu/programs',
  '/spokedu/monthly',
  '/spokedu/insights',
];

const EXPECTED_CTAS = {
  '/spokedu': [
    ['개인수업 상담', 'type=private'],
    ['기관 제안받기', 'type=dispatch'],
    ['콘텐츠 문의', 'type=curriculum'],
  ],
  '/spokedu/private': [['개인수업 상담하기', 'type=private']],
  '/spokedu/dispatch': [['기관 프로그램 제안받기', 'type=dispatch']],
  '/spokedu/curriculum': [['커리큘럼 콘텐츠 문의하기', 'type=curriculum']],
  '/spokedu/programs/spomove': [['SPOMOVE 도입 문의하기', 'type=dispatch']],
  '/spokedu/programs/paps': [['PAPS 프로그램 문의하기', 'type=dispatch']],
  '/spokedu/programs/oneday-event': [['원데이 이벤트 문의하기', 'type=dispatch']],
  '/spokedu/programs/camp': [['방학캠프 운영 문의하기', 'type=dispatch']],
  '/spokedu/records': [['기관 프로그램', 'type=dispatch']],
  '/spokedu/programs': [['상담 문의하기', 'type=dispatch']],
  '/spokedu/monthly': [['월간 수업 문의', 'type=dispatch']],
  '/spokedu/insights': [['스포키듀 수업 상담하기', '/spokedu/contact']],
  '/spokedu/about': [
    ['개인수업 상담', 'type=private'],
    ['기관 프로그램 제안', 'type=dispatch'],
    ['커리큘럼 콘텐츠 문의', 'type=curriculum'],
  ],
};

const VIEWPORTS = [360, 390, 430, 768, 1280];

const report = {
  contactLinks: {},
  contactForms: [],
  ctaHeights: [],
  footers: {},
  priorities: [],
  duplicateImages: {},
  postimg: [],
  overflow: [],
};

async function main() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  page.on('response', (r) => {
    if (/postimg/i.test(r.url())) report.postimg.push(r.url());
  });

  for (const path of PAGES) {
    await page.goto(`${BASE}${path}`, { waitUntil: 'networkidle', timeout: 45000 });
    const links = await page.evaluate(() => {
      return [...document.querySelectorAll('a[href*="contact"]')].map((a) => ({
        text: (a.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 80),
        href: a.getAttribute('href') || '',
      }));
    });
    report.contactLinks[path] = links;

    const pri = await page.evaluate(() =>
      [...document.querySelectorAll('img[fetchpriority="high"], img[loading="eager"]')].map((i) => i.src),
    );
    if (pri.length) report.priorities.push({ path, count: pri.length, srcs: pri.slice(0, 3) });

    const imgs = await page.evaluate(() =>
      [...document.querySelectorAll('img')].map((i) => i.src).filter((s) => s.includes('/images/spokedu/')),
    );
    for (const src of imgs) {
      report.duplicateImages[src] = (report.duplicateImages[src] || 0) + 1;
    }
  }

  for (const [type, titleExpect] of [
    ['private', '개인·소그룹'],
    ['dispatch', '기관 프로그램'],
    ['curriculum', '커리큘럼'],
  ]) {
    await page.goto(`${BASE}/spokedu/contact?type=${type}`, { waitUntil: 'networkidle', timeout: 45000 });
    const state = await page.evaluate((expect) => {
      const params = new URLSearchParams(location.search);
      const h3 = document.querySelector('form h3')?.textContent?.trim() || '';
      const selected = [...document.querySelectorAll('#contact-type-select button')].map((b) => ({
        text: b.querySelector('p.font-bold')?.textContent?.trim(),
        active: b.className.includes('ring-2') || b.className.includes('border-indigo-500') || b.textContent?.includes('선택됨'),
        cls: b.className.slice(0, 120),
      }));
      const phoneRequired = !!document.querySelector('input[type="tel"][required], input[name*="phone"][required]');
      const emailOptional = [...document.querySelectorAll('label')].some((l) => l.textContent?.includes('이메일') && !l.textContent?.includes('필수'));
      const footers = [...document.querySelectorAll('footer')].length;
      const privateOnly = !!document.querySelector('select, [name*="preferredClass"], input[placeholder*="아이"]');
      return { type: params.get('type'), h3, selected, phoneRequired, emailOptional, footers, hasForm: !!document.querySelector('form') };
    }, titleExpect);
    report.contactForms.push({ type, ...state, titleOk: state.h3.includes(titleExpect) });
  }

  await page.goto(`${BASE}/spokedu/contact`, { waitUntil: 'networkidle' });
  report.footers.contact = await page.evaluate(() => ({
    footers: document.querySelectorAll('footer').length,
    contactFooter: !!document.querySelector('footer')?.textContent?.includes('상담'),
  }));

  for (const vp of VIEWPORTS) {
    await page.setViewportSize({ width: vp, height: 900 });
    await page.goto(`${BASE}/spokedu/about`, { waitUntil: 'domcontentloaded' });
    const cta = await page.evaluate(() => {
      const btns = [...document.querySelectorAll('a.rounded-full')].filter((a) => a.textContent?.includes('상담') || a.textContent?.includes('제안') || a.textContent?.includes('문의'));
      return btns.map((b) => {
        const s = getComputedStyle(b);
        return { text: b.textContent?.trim().slice(0, 30), height: b.getBoundingClientRect().height, minH: s.minHeight };
      });
    });
    report.ctaHeights.push({ viewport: vp, aboutCtas: cta });
    const ox = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 2);
    if (ox) report.overflow.push({ viewport: vp, path: '/spokedu/about' });
  }

  report.ctaAudit = [];
  for (const [path, expects] of Object.entries(EXPECTED_CTAS)) {
    await page.goto(`${BASE}${path}`, { waitUntil: 'domcontentloaded', timeout: 30000 });
    for (const [labelPart, hrefPart] of expects) {
      const match = await page.evaluate(
        ({ labelPart, hrefPart }) => {
          const links = [...document.querySelectorAll('a')];
          const found = links.filter((a) => a.textContent?.includes(labelPart) && (a.getAttribute('href') || '').includes(hrefPart.replace('type=', 'type=')));
          return found.map((a) => ({ text: a.textContent?.trim().slice(0, 50), href: a.getAttribute('href') }));
        },
        { labelPart, hrefPart },
      );
      report.ctaAudit.push({
        page: path,
        labelPart,
        hrefPart,
        ok: match.length > 0,
        matches: match.slice(0, 3),
      });
    }
  }

  await browser.close();
  const out = join(OUT_DIR, 'report-deep.json');
  writeFileSync(out, JSON.stringify(report, null, 2));
  console.log('Deep report:', out);
  console.log('Postimg:', report.postimg.length);
  console.log('CTA audit fails:', report.ctaAudit.filter((c) => !c.ok).length);
  console.log('Contact form fails:', report.contactForms.filter((c) => !c.titleOk).length);
  for (const c of report.ctaAudit.filter((x) => !x.ok)) {
    console.log('FAIL', c.page, c.labelPart, JSON.stringify(c.matches));
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/**
 * Spokedu 통합 QA — Playwright headless
 * Usage: node scripts/spokedu-qa.mjs [baseUrl]
 */
import { chromium } from 'playwright';
import { writeFileSync, mkdirSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const BASE = process.argv[2] || 'http://localhost:3000';
const VIEWPORTS = [
  { name: '360', width: 360, height: 800 },
  { name: '390', width: 390, height: 844 },
  { name: '430', width: 430, height: 932 },
  { name: '768', width: 768, height: 1024 },
  { name: 'desktop', width: 1280, height: 900 },
];

const PAGES = [
  '/spokedu',
  '/spokedu/about',
  '/spokedu/private',
  '/spokedu/dispatch',
  '/spokedu/curriculum',
  '/spokedu/programs/spomove',
  '/spokedu/programs/paps',
  '/spokedu/programs/oneday-event',
  '/spokedu/programs/camp',
  '/spokedu/records',
  '/spokedu/programs',
  '/spokedu/monthly',
  '/spokedu/monthly/2026-05',
  '/spokedu/insights',
  '/spokedu/contact',
  '/spokedu/contact?type=private',
  '/spokedu/contact?type=dispatch',
  '/spokedu/contact?type=curriculum',
];

const CTA_CHECKS = [
  { page: '/spokedu', linkText: /개인수업 상담/, href: /type=private/ },
  { page: '/spokedu', linkText: /기관 제안|기관 프로그램/, href: /type=dispatch/ },
  { page: '/spokedu/private', linkText: /개인수업/, href: /type=private/ },
  { page: '/spokedu/dispatch', linkText: /제안|문의/, href: /type=dispatch/ },
  { page: '/spokedu/curriculum', linkText: /커리큘럼|문의/, href: /type=curriculum/ },
  { page: '/spokedu/about', linkText: /개인수업 상담/, href: /type=private/ },
];

const OUT_DIR = join(__dirname, '../.qa-spokedu');
mkdirSync(OUT_DIR, { recursive: true });

const report = {
  base: BASE,
  timestamp: new Date().toISOString(),
  pageResults: [],
  network: { postimg: [], failedImages: [], status404: [] },
  contact: [],
  cta: [],
  heroSamples: [],
  errors: [],
};

function grade(status, issues) {
  if (status >= 500 || issues.some((i) => i.severity === 'critical')) return 'D';
  if (issues.filter((i) => i.severity === 'high').length >= 2) return 'C';
  if (issues.length > 0) return 'B';
  return 'A';
}

async function main() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();

  page.on('response', (res) => {
    const url = res.url();
    if (/postimg/i.test(url)) report.network.postimg.push(url);
    if (res.status() === 404) report.network.status404.push({ url, page: report._currentPage });
    if (res.status() >= 400 && /\.(jpg|jpeg|png|webp|gif|svg)/i.test(url)) {
      report.network.failedImages.push({ url, status: res.status() });
    }
  });

  for (const path of PAGES) {
    report._currentPage = path;
    const issues = [];
    let status = 0;
    let title = '';
    let h1Text = '';
    let footerCount = 0;
    let postimgOnPage = 0;

    try {
      const res = await page.goto(`${BASE}${path}`, { waitUntil: 'networkidle', timeout: 45000 });
      status = res?.status() ?? 0;
      if (status >= 400) issues.push({ severity: 'critical', msg: `HTTP ${status}` });

      title = await page.title();
      const h1 = page.locator('h1').first();
      if ((await h1.count()) > 0) h1Text = (await h1.innerText()).replace(/\s+/g, ' ').trim();

      footerCount = await page.locator('footer').count();
      if (path.startsWith('/spokedu/contact') && footerCount > 1) {
        issues.push({ severity: 'high', msg: `Contact footer 중복: ${footerCount}개` });
      }

      const brokenImgs = await page.evaluate(() => {
        return [...document.querySelectorAll('img')].filter((img) => {
          const complete = img.complete;
          const natural = img.naturalWidth;
          return complete && natural === 0 && img.src && !img.src.startsWith('data:');
        }).map((img) => img.src);
      });
      if (brokenImgs.length) {
        issues.push({ severity: 'high', msg: `깨진 img ${brokenImgs.length}개`, detail: brokenImgs.slice(0, 5) });
      }

      if (path.includes('contact')) {
        const active = await page.evaluate(() => {
          const cards = [...document.querySelectorAll('#contact-type-select button, #contact-type-select [role="button"]')];
          const selected = document.querySelector('#contact-type-select [aria-pressed="true"], #contact-type-select button[class*="ring"], #contact-type-select button.border-indigo-600');
          const params = new URLSearchParams(window.location.search);
          const type = params.get('type') || 'private';
          const buttons = [...document.querySelectorAll('#contact-type-select button')];
          const activeBtn = buttons.find((b) => b.getAttribute('aria-pressed') === 'true' || b.className.includes('ring-2') || b.className.includes('border-indigo-600'));
          const activeId = activeBtn?.textContent?.trim() || '';
          const formVisible = !!document.querySelector('form');
          return { type, activeId, formVisible, buttonCount: buttons.length };
        });
        report.contact.push({ path, ...active });
      }

      if (path === '/spokedu/monthly/2026-05' && status === 404) {
        issues.push({ severity: 'high', msg: 'monthly/2026-05 404' });
      }
    } catch (e) {
      issues.push({ severity: 'critical', msg: String(e.message || e) });
    }

    report.pageResults.push({
      path,
      status,
      grade: grade(status, issues),
      title,
      h1: h1Text.slice(0, 120),
      footerCount,
      issues,
    });
  }

  for (const vp of VIEWPORTS.slice(0, 3)) {
    await page.setViewportSize({ width: vp.width, height: vp.height });
    for (const path of ['/spokedu', '/spokedu/about', '/spokedu/contact']) {
      try {
        await page.goto(`${BASE}${path}`, { waitUntil: 'domcontentloaded', timeout: 30000 });
        const hero = await page.evaluate(() => {
          const h1 = document.querySelector('h1');
          const rect = h1?.getBoundingClientRect();
          const subs = document.querySelector('p');
          return {
            h1Lines: h1?.innerText?.split('\n').map((l) => l.trim()).filter(Boolean),
            h1Width: rect?.width,
            overflowX: document.documentElement.scrollWidth > window.innerWidth + 2,
          };
        });
        report.heroSamples.push({ viewport: vp.name, path, ...hero });
        const shot = join(OUT_DIR, `hero-${vp.name}-${path.replace(/\//g, '_')}.png`);
        await page.screenshot({ path: shot, fullPage: false });
      } catch (e) {
        report.errors.push({ viewport: vp.name, path, error: String(e) });
      }
    }
  }

  await page.setViewportSize({ width: 390, height: 844 });
  for (const check of CTA_CHECKS) {
    try {
      await page.goto(`${BASE}${check.page}`, { waitUntil: 'domcontentloaded', timeout: 30000 });
      const link = page.getByRole('link', { name: check.linkText }).first();
      const href = (await link.count()) > 0 ? await link.getAttribute('href') : null;
      const ok = href && check.href.test(href);
      report.cta.push({ page: check.page, href, ok, expected: String(check.href) });
    } catch (e) {
      report.cta.push({ page: check.page, error: String(e) });
    }
  }

  await browser.close();
  const outPath = join(OUT_DIR, 'report.json');
  writeFileSync(outPath, JSON.stringify(report, null, 2));
  console.log('QA report:', outPath);
  console.log('Pages:', report.pageResults.length);
  console.log('Postimg:', report.network.postimg.length);
  console.log('404 responses:', report.network.status404.length);
  console.log('Failed images:', report.network.failedImages.length);
  for (const p of report.pageResults.filter((r) => r.grade !== 'A')) {
    console.log(`${p.grade} ${p.path}:`, p.issues.map((i) => i.msg).join('; '));
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/**
 * Spokedu Release Candidate QA
 */
import { chromium } from 'playwright';
import { writeFileSync, mkdirSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const BASE = process.argv[2] || 'http://localhost:3000';
const OUT = join(__dirname, '../.qa-spokedu/rc-report.json');
mkdirSync(dirname(OUT), { recursive: true });

const VIEWPORTS = [360, 390, 430, 768, 1280];
const NAV_PATHS = [
  '/spokedu',
  '/spokedu/about',
  '/spokedu/private',
  '/spokedu/dispatch',
  '/spokedu/curriculum',
  '/spokedu/records',
  '/spokedu/programs',
  '/spokedu/monthly',
  '/spokedu/insights',
  '/spokedu/contact',
];

const report = {
  base: BASE,
  timestamp: new Date().toISOString(),
  homeAbout: {},
  contact: [],
  mobile: [],
  links: { broken: [], ok: 0 },
  network: { postimg: [], img404: [], consoleErrors: [] },
  seo: {},
  perf: {},
};

const TEST_NAME = '테스트 문의입니다 - 삭제 가능';
const TEST_PHONE = '010-0000-0001';

async function fillCommon(page) {
  await page.locator('input[autocomplete="name"]').fill(TEST_NAME);
  await page.locator('input[autocomplete="tel"]').fill(TEST_PHONE);
  await page.locator('textarea').first().fill('RC QA 테스트 문의입니다. 삭제 가능.');
  const region = page.locator('input[placeholder*="서울"]');
  if ((await region.count()) > 0) await region.fill('서울 테스트');
}

async function testContactType(page, type) {
  const result = { type, url: `${BASE}/spokedu/contact?type=${type}` };
  const apiCalls = [];
  page.on('request', (req) => {
    if (req.method() === 'POST' && /\/api\/(private|dispatch|curriculum)\/leads/.test(req.url())) {
      apiCalls.push({ url: req.url(), postData: req.postData() });
    }
  });

  await page.goto(result.url, { waitUntil: 'networkidle', timeout: 45000 });
  result.h3 = await page.locator('form h3').innerText().catch(() => '');
  result.activeCard = await page.evaluate((t) => {
    const btn = [...document.querySelectorAll('#contact-type-select button')].find((b) =>
      b.textContent?.includes('선택됨'),
    );
    return btn?.querySelector('p.font-bold')?.textContent?.trim() || '';
  }, type);

  const emailReq = await page.locator('input[autocomplete="email"]').getAttribute('required');
  result.emailRequired = emailReq !== null && emailReq !== '';

  await fillCommon(page);

  if (type === 'private') {
    const age = page.locator('input').filter({ has: page.locator('xpath=..') });
    const childAge = page.getByLabel(/아이 연령|연령/i).first();
    if ((await childAge.count()) > 0) await childAge.fill('초등 1학년');
  }
  if (type === 'dispatch') {
    const org = page.getByLabel(/기관명/i).first();
    if ((await org.count()) > 0) await org.fill('RC 테스트 기관');
    const participants = page.getByLabel(/예상 인원/i).first();
    if ((await participants.count()) > 0) await participants.fill('20');
  }
  if (type === 'curriculum') {
    const org = page.getByLabel(/기관명|소속/i).first();
    if ((await org.count()) > 0) await org.fill('RC 테스트 소속');
  }

  const submit = page.locator('form button[type="submit"]');
  await submit.click();
  await page.waitForTimeout(2500);

  result.apiCalls = apiCalls;
  result.notice = await page.locator('[role="status"], .rounded-xl').filter({ hasText: /접수|문제/ }).first().innerText().catch(() => {
    return page.evaluate(() => {
      const el = [...document.querySelectorAll('p, div')].find((n) =>
        /접수|문제가 발생/.test(n.textContent || ''),
      );
      return el?.textContent?.trim().slice(0, 200) || '';
    });
  });

  const noEmailSubmit = !result.notice.includes('문제');
  result.submittedWithoutEmail = noEmailSubmit;
  return result;
}

async function main() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();

  page.on('console', (msg) => {
    if (msg.type() === 'error') report.network.consoleErrors.push(msg.text().slice(0, 200));
  });
  page.on('response', (r) => {
    const u = r.url();
    if (/postimg/i.test(u)) report.network.postimg.push(u);
    if (r.status() === 404) report.network.img404.push(u);
  });

  await page.goto(`${BASE}/spokedu`, { waitUntil: 'networkidle', timeout: 45000 });
  const homeH1 = await page.locator('h1').first().innerText();
  await page.goto(`${BASE}/spokedu/about`, { waitUntil: 'networkidle', timeout: 45000 });
  const aboutH1 = await page.locator('h1').first().innerText();
  report.homeAbout = {
    homeH1: homeH1.replace(/\s+/g, ' ').trim(),
    aboutH1: aboutH1.replace(/\s+/g, ' ').trim(),
    identical: homeH1.replace(/\n/g, '') === aboutH1.replace(/\n/g, ''),
  };

  for (const type of ['private', 'dispatch', 'curriculum']) {
    const p = await context.newPage();
    report.contact.push(await testContactType(p, type));
    await p.close();
  }

  for (const vp of VIEWPORTS) {
    await page.setViewportSize({ width: vp, height: 900 });
    const samples = [];
    for (const path of ['/spokedu', '/spokedu/about', '/spokedu/contact', '/spokedu/records', '/spokedu/programs', '/spokedu/programs/spomove']) {
      await page.goto(`${BASE}${path}`, { waitUntil: 'domcontentloaded', timeout: 30000 });
      const m = await page.evaluate(() => {
        const h1 = document.querySelector('h1');
        const ctas = [...document.querySelectorAll('a.rounded-full')].filter((a) =>
          /상담|제안|문의/.test(a.textContent || ''),
        );
        return {
          path: location.pathname,
          h1Lines: h1?.innerText?.split('\n').filter(Boolean).length || 0,
          overflow: document.documentElement.scrollWidth > window.innerWidth + 2,
          ctaHeights: ctas.slice(0, 4).map((b) => Math.round(b.getBoundingClientRect().height)),
          ctaTwoLine: ctas.some((b) => b.getBoundingClientRect().height > 56),
        };
      });
      samples.push({ viewport: vp, ...m });
    }
    report.mobile.push({ viewport: vp, samples });
  }

  await page.goto(`${BASE}/spokedu`, { waitUntil: 'networkidle' });
  const hrefs = await page.evaluate(() => {
    const base = location.origin;
    return [...document.querySelectorAll('a[href]')].map((a) => {
      const h = a.getAttribute('href') || '';
      try {
        return new URL(h, base).pathname + (new URL(h, base).search || '');
      } catch {
        return h;
      }
    });
  });
  const unique = [...new Set(hrefs)].filter((h) => h.startsWith('/spokedu') || h.startsWith('/api'));
  for (const h of unique.slice(0, 40)) {
    if (h.startsWith('#')) continue;
    try {
      const r = await page.request.get(`${BASE}${h.split('?')[0]}`, { timeout: 15000 });
      if (r.status() >= 400) report.links.broken.push({ href: h, status: r.status() });
      else report.links.ok++;
    } catch (e) {
      report.links.broken.push({ href: h, error: String(e) });
    }
  }

  for (const path of NAV_PATHS) {
    await page.goto(`${BASE}${path}`, { waitUntil: 'domcontentloaded' });
  }
  report.seo = {
    home: await page.evaluate(() => ({ title: document.title, desc: document.querySelector('meta[name="description"]')?.content })),
  };
  await page.goto(`${BASE}/spokedu/about`);
  report.seo.about = await page.evaluate(() => ({
    title: document.title,
    og: document.querySelector('meta[property="og:image"]')?.content || '',
  }));
  await page.goto(`${BASE}/spokedu/contact`);
  report.seo.contact = await page.evaluate(() => ({
    title: document.title,
    desc: document.querySelector('meta[name="description"]')?.content,
  }));
  await page.goto(`${BASE}/spokedu/monthly/2026-05`);
  report.seo.monthlyDetail = await page.evaluate(() => document.title);

  const t0 = Date.now();
  await page.goto(`${BASE}/spokedu`, { waitUntil: 'load' });
  report.perf.homeLoadMs = Date.now() - t0;
  const lcpHint = await page.evaluate(() => {
    const img = document.querySelector('img');
    return img?.currentSrc?.slice(0, 120) || '';
  });
  report.perf.firstImg = lcpHint;

  await browser.close();
  writeFileSync(OUT, JSON.stringify(report, null, 2));
  console.log('RC report written:', OUT);
  console.log('Home H1:', report.homeAbout.homeH1);
  console.log('About H1:', report.homeAbout.aboutH1);
  console.log('Contact tests:', report.contact.length);
  console.log('Broken links:', report.links.broken.length);
  console.log('Console errors:', report.network.consoleErrors.length);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
